def _breakpoint_static_points_from_material_confirmation_payload(
    payload: dict[str, object],
) -> dict[str, list[dict[str, object]]]:
    if not _producer_material_confirmation_allows_breakpoint(payload):
        return {}
    out: dict[str, list[dict[str, object]]] = {}
    points = payload.get("confirmed_material_hook_candidates", [])
    if not isinstance(points, list):
        return {}
    for point in points:
        if not isinstance(point, dict):
            continue
        kind = str(point.get("kind", "")).strip()
        if kind not in BASE64_RC4_BREAKPOINT_READY_KINDS:
            continue
        module_offset = _static_point_module_offset(point.get("module_offset"))
        if module_offset is None:
            continue
        out.setdefault(kind, []).append(
            {
                **point,
                "hook_kind": str(point.get("hook_kind", "interceptor") or "interceptor"),
                "module_offset": module_offset,
                "rva": f"0x{module_offset:x}",
                "hookable": True,
            }
        )
    return out


def _profile_audit_candidate_record(
    *,
    label: str,
    source: str,
    candidate_hex: str,
    runtime_entry: dict[str, object] | None = None,
    promotion_allowed: bool = True,
) -> dict[str, object]:
    runtime_entry = runtime_entry or {}
    normalized = str(candidate_hex).strip().lower()
    trace = trace_candidate_transform(normalized)
    runtime_prefix = str(
        runtime_entry.get("runtime_lhs_prefix_hex_10")
        or str(runtime_entry.get("runtime_lhs_prefix_hex") or "")[: len(TARGET_PREFIX) * 2]
        or ""
    ).strip().lower()
    if not runtime_prefix and normalized.startswith("78d540b49c590770"):
        runtime_prefix = "46006c004464830d311c"
    if not runtime_prefix and normalized.startswith("4a78f0eaeb4f13b0"):
        runtime_prefix = "46004c007e40b92886f5"
    compare_boundary = dict(trace.get("compare_boundary", {})) if isinstance(trace.get("compare_boundary"), dict) else {}
    decrypt_prefix = str(dict(trace.get("rc4", {})).get("decrypt_prefix_hex", "")).strip().lower()
    offline_prefix_10 = decrypt_prefix[: len(TARGET_PREFIX) * 2]
    return {
        "label": label,
        "source": source,
        "candidate_hex": normalized,
        "cand8_hex": normalized[:16],
        "promotion_allowed": bool(promotion_allowed),
        "runtime_prefix_hex_10": runtime_prefix,
        "offline_prefix_hex_10": offline_prefix_10,
        "offline_runtime_prefix_agree_10": bool(runtime_prefix) and runtime_prefix == offline_prefix_10,
        "runtime_ci_exact_wchars": runtime_entry.get("runtime_ci_exact_wchars"),
        "runtime_ci_distance5": runtime_entry.get("runtime_ci_distance5"),
        "compare_semantics_agree": runtime_entry.get("compare_semantics_agree"),
        "trace": trace,
        "summary": {
            "candidate_length_bytes": dict(trace.get("candidate_layout", {})).get("candidate_length_bytes"),
            "prefix_bytes": dict(trace.get("candidate_layout", {})).get("prefix_bytes"),
            "base64_length_chars": dict(trace.get("base64_boundary", {})).get("base64_length_chars"),
            "prefix_ends_on_base64_chunk_boundary": dict(trace.get("base64_boundary", {})).get(
                "prefix_ends_on_base64_chunk_boundary"
            ),
            "prefix_last_chunk_raw_remainder": dict(trace.get("base64_boundary", {})).get(
                "prefix_last_chunk_raw_remainder"
            ),
            "rc4_key_length_bytes": dict(trace.get("rc4", {})).get("key_length_bytes"),
            "ci_exact_wchars": compare_boundary.get("ci_exact_wchars"),
            "ci_distance5": compare_boundary.get("ci_distance5"),
        },
    }


def _profile_transform_audit_candidates(
    *,
    runtime_validations: Sequence[dict[str, object]],
    top_entries: Sequence[dict[str, object]],
    exact2_basin_value_pool_payload: dict[str, object],
) -> list[dict[str, object]]:
    candidates: list[dict[str, object]] = []
    seen: set[str] = set()

    def _push(
        label: str,
        source: str,
        candidate_hex: str,
        runtime_entry: dict[str, object] | None = None,
        *,
        promotion_allowed: bool = True,
    ) -> None:
        normalized = str(candidate_hex).strip().lower()
        if not normalized or len(normalized) != INPUT_LENGTH * 2 or normalized in seen:
            return
        if len(candidates) >= PROFILE_TRANSFORM_AUDIT_CANDIDATE_LIMIT:
            return
        seen.add(normalized)
        candidates.append(
            _profile_audit_candidate_record(
                label=label,
                source=source,
                candidate_hex=normalized,
                runtime_entry=runtime_entry,
                promotion_allowed=promotion_allowed,
            )
        )

    all_validations = [
        dict(item)
        for item in runtime_validations
        if isinstance(item, dict) and bool(item.get("compare_semantics_agree"))
    ]
    exact2_runtime = next(
        (
            item
            for item in sorted(all_validations, key=_runtime_validation_sort_key)
            if int(item.get("runtime_ci_exact_wchars", 0) or 0) >= 2
        ),
        None,
    )
    if exact2_runtime:
        _push(
            "current_exact2_best",
            "current_run_runtime_validation",
            _candidate_hex_from_entry(exact2_runtime),
            exact2_runtime,
        )
    else:
        state_exact2 = _candidate_from_project_state("exact2")
        _push(
            "current_exact2_best",
            "project_state.current_state.best_candidates.exact2",
            _candidate_hex_from_entry(state_exact2) or "78d540b49c59077041414141414141",
            state_exact2,
        )

    exact1_runtime = _best_compare_agree_frontier_entry_for_exact(all_validations, 1)
    if exact1_runtime:
        _push(
            "exact1_frontier_best",
            "current_run_runtime_validation",
            _candidate_hex_from_entry(exact1_runtime),
            exact1_runtime,
        )
    else:
        state_exact1 = _candidate_from_project_state("exact1")
        _push(
            "exact1_frontier_best",
            "project_state.current_state.best_candidates.exact1",
            _candidate_hex_from_entry(state_exact1),
            state_exact1,
        )

    _push(
        "secondary_exact2_reference",
        "project_handoff_reference",
        "4a78f0eaeb4f13b041414141414141",
    )
    for anchor in DO_NOT_PROMOTE_PROJECTED_ANCHORS:
        _push(
            f"projected_do_not_promote_{anchor}",
            "project_state.do_not_do_projected_example",
            f"{anchor}{DEFAULT_FIXED_SUFFIX_HEX}",
            promotion_allowed=False,
        )

    for entry in top_entries:
        if len(candidates) >= PROFILE_TRANSFORM_AUDIT_CANDIDATE_LIMIT - 1:
            break
        _push("frontier_top_entry", "current_run_top_entries", _candidate_hex_from_entry(dict(entry)), dict(entry))

    value_pool_best = exact2_basin_value_pool_payload.get("best_runtime_candidate", {})
    if isinstance(value_pool_best, dict):
        _push(
            "exact2_value_pool_best_runtime",
            "latest_indexed_exact2_basin_value_pool_result",
            _candidate_hex_from_entry(value_pool_best),
            value_pool_best,
        )

    _push("probe_all_A_baseline", "probe_baseline", "414141414141414141414141414141")
    return candidates[:PROFILE_TRANSFORM_AUDIT_CANDIDATE_LIMIT]


def run_profile_transform_hypothesis_audit(
    *,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    runtime_validations: Sequence[dict[str, object]],
    top_entries: Sequence[dict[str, object]],
    exact2_basin_value_pool_run: dict[str, object] | None = None,
    smt_run: dict[str, object] | None = None,
    exact2_basin_smt_run: dict[str, object] | None = None,
    frontier_summary_path: Path | None = None,
    strata_summary_path: Path | None = None,
    search_budget: int | None = None,
    snapshot_interval: int | None = None,
    validate_top: int | None = None,
    per_probe_timeout: float | None = None,
    log: Any | None = None,
) -> dict[str, object]:
    _ = transform_model
    latest_value_pool_payload, latest_value_pool_path = _indexed_artifact_payload("exact2_basin_value_pool_result")
    if exact2_basin_value_pool_run and isinstance(exact2_basin_value_pool_run.get("payload"), dict):
        value_pool_payload = dict(exact2_basin_value_pool_run["payload"])
        value_pool_path = str(exact2_basin_value_pool_run.get("result_path", "")) or latest_value_pool_path
    else:
        value_pool_payload = latest_value_pool_payload
        value_pool_path = latest_value_pool_path

    candidates = _profile_transform_audit_candidates(
        runtime_validations=runtime_validations,
        top_entries=top_entries,
        exact2_basin_value_pool_payload=value_pool_payload,
    )
    exact2_record = next((item for item in candidates if item["label"] == "current_exact2_best"), {})
    helper_runtime_consistent = bool(exact2_record.get("offline_runtime_prefix_agree_10"))
    any_runtime_disagreement = any(
        item.get("runtime_prefix_hex_10") and not item.get("offline_runtime_prefix_agree_10")
        for item in candidates
    )
    negative_recorded = _negative_exact2_value_pool_recorded()
    exhausted_branch = {
        "branch": "exact2_basin_value_pool",
        "attempted": bool(value_pool_payload.get("attempted")),
        "classification": str(value_pool_payload.get("classification", "")),
        "generated_count": int(value_pool_payload.get("generated_count", 0) or 0),
        "unique_count": int(value_pool_payload.get("unique_count", 0) or 0),
        "validated_count": int(value_pool_payload.get("validated_count", 0) or 0),
        "best_candidate": str(
            dict(value_pool_payload.get("best_runtime_candidate", {})).get(
                "candidate_hex",
                value_pool_payload.get("best_candidate", ""),
            )
        ),
        "best_runtime_exact_wchars": int(
            dict(value_pool_payload.get("best_runtime_candidate", {})).get(
                "runtime_ci_exact_wchars",
                value_pool_payload.get("best_runtime_exact_wchars", 0),
            )
            or 0
        ),
        "best_runtime_distance5": int(
            dict(value_pool_payload.get("best_runtime_candidate", {})).get(
                "runtime_ci_distance5",
                value_pool_payload.get("best_runtime_distance5", 1 << 30),
            )
            or (1 << 30)
        ),
        "improved_over_exact2": bool(value_pool_payload.get("improved_over_exact2")),
        "negative_result_recorded": negative_recorded,
        "do_not_repeat": bool(negative_recorded),
        "artifact": value_pool_path,
    }

    trace_artifacts = [
        item
        for item in [
            "project_state/artifact_index.json",
            "project_state/current_state.json",
            "project_state/negative_results.json",
            str(frontier_summary_path) if frontier_summary_path else "",
            str(strata_summary_path) if strata_summary_path else "",
            value_pool_path,
        ]
        if item
    ]
    hypothesis_matrix = [
        {
            "id": "H1",
            "hypothesis": "candidate byte layout / prefix length is wrong or too narrow",
            "evidence_for": [
                "The active line is fixed at L15(prefix8), while compare evidence is judged over the first five UTF-16LE wchars.",
                "The exact2 best stabilizes on f/l but current local mutations do not move the third wchar to an exact match.",
            ],
            "evidence_against": [
                "The exact2 baseline trace is runtime-consistent at the 5-wchar prefix.",
                "No candidate generation, ranking, or final selection change was made in this audit.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Trace at most 8 existing candidates and compare prefix8/suffix layout against the 5-wchar boundary; do not generate new search candidates.",
            "success_signal": "A contrast candidate shows the same early score but a different prefix/suffix or suffix-influenced Base64 boundary that explains the exact2 stall.",
            "stop_condition": "If traces show the fixed prefix8 boundary is internally consistent for all audit candidates, do not widen this branch without a separate bounded contrast design.",
            "code_change_allowed": "metadata_only",
            "recommendation": "primary_next_target" if helper_runtime_consistent else "blocked_until_helper_runtime_consistency",
        },
        {
            "id": "H2",
            "hypothesis": "UTF-16LE wchar boundary and byte mutation positions are offset",
            "evidence_for": [
                "Candidate bytes are nibble-expanded before UTF-16LE interleaving, so one candidate byte maps to four raw bytes before Base64.",
                "The third wchar failure appears immediately after two exact UTF-16LE pairs.",
            ],
            "evidence_against": [
                "The trace helper reproduces the known exact2 runtime prefix when helper/runtime consistency is true.",
                "Current wchar deltas align target pairs as f, l, a, g, {.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Compare nibble expansion, UTF-16 raw bytes, and wchar deltas for the audit candidates only.",
            "success_signal": "A trace shows a systematic one-byte or one-wchar shift between mutation positions and compare pairs.",
            "stop_condition": "If exact2 offline/runtime prefix and wchar deltas align, demote H2 and avoid transform changes.",
            "code_change_allowed": "metadata_only",
            "recommendation": "secondary",
        },
        {
            "id": "H3",
            "hypothesis": "Base64 boundary / padding / chunk alignment has an off-by-one",
            "evidence_for": [
                "The prefix8 raw payload is 32 bytes, which leaves remainder 2 inside a Base64 3-byte chunk.",
                "The first suffix byte therefore begins inside the Base64 chunk covering the prefix boundary.",
            ],
            "evidence_against": [
                "The current helper/runtime exact2 prefix consistency argues against a simple Base64 implementation mismatch.",
                "The audit has not generated contrast candidates, only trace metadata.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Use no more than 8 hand-picked contrast candidates to vary only the boundary-adjacent byte layout in a later run.",
            "success_signal": "A minimal contrast changes third-to-fifth wchar deltas through Base64 chunk alignment without losing runtime consistency.",
            "stop_condition": "If boundary traces are identical across best/frontier/projected examples, stop and move to candidate-quality evidence.",
            "code_change_allowed": "metadata_only_now; later_contrast_candidates_only",
            "recommendation": "primary_next_target" if helper_runtime_consistent else "blocked_until_helper_runtime_consistency",
        },
        {
            "id": "H4",
            "hypothesis": "RC4 helper and runtime are inconsistent",
            "evidence_for": [
                "Any offline/runtime prefix mismatch in the audit candidate table would immediately support this.",
            ]
            if any_runtime_disagreement
            else [
                "No direct evidence in this audit unless a runtime prefix mismatch appears.",
            ],
            "evidence_against": [
                "The exact2 baseline offline trace matches the known runtime prefix."
            ]
            if helper_runtime_consistent
            else [
                "The exact2 baseline did not prove helper/runtime consistency in this matrix.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Stop search and compare RC4 key prefix/key length/decrypt prefix for existing runtime-validated candidates.",
            "success_signal": "Any compare_semantics_agree candidate has runtime prefix different from trace decrypt_prefix.",
            "stop_condition": "If exact2 and secondary exact2 prefixes match runtime, demote H4 for the next iteration.",
            "code_change_allowed": "trace_or_helper_fix_only_if_mismatch",
            "recommendation": "stop_and_fix_first" if any_runtime_disagreement else "demote",
        },
        {
            "id": "H5",
            "hypothesis": "offline compare-aware semantics skew from runtime in this basin",
            "evidence_for": [
                "Would be supported by compare_semantics_agree=false or metric deltas among audit candidates.",
            ],
            "evidence_against": [
                "Current exact2 value-pool validations were runtime checked and compare_semantics_agree=true.",
                "The negative branch was recorded after validating all 18 bounded combinations.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Contrast offline ci_exact/distance5 with runtime ci_exact/distance5 for existing validation rows only.",
            "success_signal": "A repeated metric divergence appears among compare_semantics_agree=true candidates.",
            "stop_condition": "If offline/runtime metrics agree for exact2 and value-pool rows, demote H5.",
            "code_change_allowed": "metadata_only",
            "recommendation": "demote" if helper_runtime_consistent else "inspect_with_H4",
        },
        {
            "id": "H6",
            "hypothesis": "current exact2 candidate is locally optimal under available evidence; candidate quality is insufficient",
            "evidence_for": [
                "The exact2 basin value-pool branch generated and runtime-validated all 18 diagnostic combinations with no exact3+ or distance5 improvement.",
                "negative_results.json records this pool as do_not_repeat.",
            ],
            "evidence_against": [
                "This is not an unsat proof for the full input space; it only closes the current diagnostic pool.",
            ],
            "files_or_artifacts_needed": trace_artifacts,
            "bounded_validation": "Do not repeat the exhausted pool; only choose a new bounded contrast if H1/H3 trace evidence justifies it.",
            "success_signal": "A new evidence source identifies a smaller, different candidate family than the exhausted value pool.",
            "stop_condition": "If no H1/H3/H4/H5 evidence appears, stop local mutation and request a different evidence source.",
            "code_change_allowed": "metadata_only",
            "recommendation": "fallback_after_H1_H3_audit",
        },
    ]
    next_target = (
        {
            "selected_hypotheses": ["H4", "H5"],
            "reason": "offline/runtime prefix consistency failed or could not be established",
            "bounded_validation": "Stop candidate search and repair/verify transform or RC4 trace assumptions first.",
        }
        if not helper_runtime_consistent or any_runtime_disagreement
        else {
            "selected_hypotheses": ["H1", "H3"],
            "reason": "helper/runtime prefix is consistent, while prefix8 raw bytes end inside a Base64 chunk boundary.",
            "bounded_validation": "Next run should use a tiny hand-picked contrast set around prefix8 + Base64 chunk boundary; this run only emits trace metadata.",
        }
    )
    payload = {
        "artifact_kind": "profile_transform_hypothesis_matrix",
        "profile": "samplereverse",
        "audit_only": True,
        "candidate_limit": PROFILE_TRANSFORM_AUDIT_CANDIDATE_LIMIT,
        "candidate_count": len(candidates),
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "settings_snapshot": {
            "search_budget": search_budget,
            "snapshot_interval": snapshot_interval,
            "validate_top": validate_top,
            "per_probe_timeout": per_probe_timeout,
            "frontier_max_iterations": FRONTIER_MAX_ITERATIONS,
            "guided_pool_beam_limit": GUIDED_POOL_BEAM_LIMIT,
        },
        "read_scope": {
            "uses_latest_indexed_artifacts_only": True,
            "scans_full_solve_reports": False,
            "read_artifacts": trace_artifacts,
        },
        "exhausted_branch_confirmation": exhausted_branch,
        "candidates": candidates,
        "hypotheses": hypothesis_matrix,
        "next_bounded_validation_target": {
            **next_target,
            "candidate_count_allowed": PROFILE_TRANSFORM_AUDIT_CANDIDATE_LIMIT,
            "runtime_validation_required": True,
            "expected_improvement_signal": "runtime_ci_exact_wchars > 2 or runtime_ci_distance5 < 246 without compare_semantics disagreement",
            "stop_condition": "Do not expand beam/budget/topN/timeout/frontier iterations; stop if trace shows helper/runtime mismatch.",
        },
        "smt_context": {
            "primary_smt_summary": str(dict((smt_run or {}).get("payload", {})).get("summary", "")),
            "exact2_basin_smt_summary": str(
                dict((exact2_basin_smt_run or {}).get("payload", {})).get("summary", "")
            ),
        },
    }
    output_path = artifacts_dir / PROFILE_TRANSFORM_HYPOTHESIS_MATRIX_FILE_NAME
    _write_json(output_path, payload)
    if log:
        log(f"profile transform hypothesis audit wrote {output_path}")
    return {"result_path": str(output_path), "payload": payload}


def _h1_h3_boundary_validation_entries(
    transform_model: SamplereverseTransformModel,
) -> list[dict[str, object]]:
    entries: list[dict[str, object]] = []
    seen: set[str] = set()
    for label, candidate_hex, layout_hypothesis, boundary_focus in H1_H3_BOUNDARY_CANDIDATES:
        normalized = str(candidate_hex).strip().lower()
        if normalized in seen or len(normalized) != INPUT_LENGTH * 2:
            continue
        seen.add(normalized)
        entry = _evaluate_candidate_hex(normalized, transform_model)
        trace_prefix7 = trace_candidate_transform(normalized, prefix_bytes=7)
        trace_prefix8 = trace_candidate_transform(normalized, prefix_bytes=8)
        trace_prefix9 = trace_candidate_transform(normalized, prefix_bytes=9)
        compare_boundary = (
            dict(trace_prefix8.get("compare_boundary", {}))
            if isinstance(trace_prefix8.get("compare_boundary"), dict)
            else {}
        )
        offline_prefix_hex_10 = str(compare_boundary.get("raw_prefix_hex_10", "")).strip().lower()
        entry.update(
            {
                "label": label,
                "stage": "h1_h3_boundary_validation",
                "frontier_role": "h1_h3_boundary_contrast",
                "anchor_mode": EXACT2_ANCHOR_MODE,
                "source_anchor": "78d540b49c590770",
                "base_anchor": "78d540b49c590770",
                "anchor_lineage": "exact2_seed(78d540b49c590770) -> h1_h3_boundary_validation",
                "layout_hypothesis": layout_hypothesis,
                "boundary_focus": boundary_focus,
                "trace_prefix7": trace_prefix7,
                "trace_prefix8": trace_prefix8,
                "trace_prefix9": trace_prefix9,
                "offline_prefix_hex_10": offline_prefix_hex_10,
                "base64_remainders": {
                    "prefix7": dict(trace_prefix7.get("base64_boundary", {})).get(
                        "prefix_last_chunk_raw_remainder"
                    ),
                    "prefix8": dict(trace_prefix8.get("base64_boundary", {})).get(
                        "prefix_last_chunk_raw_remainder"
                    ),
                    "prefix9": dict(trace_prefix9.get("base64_boundary", {})).get(
                        "prefix_last_chunk_raw_remainder"
                    ),
                },
            }
        )
        entries.append(entry)
    return entries[:H1_H3_BOUNDARY_CANDIDATE_LIMIT]


def _selected_h1_h3_target(profile_transform_audit_run: dict[str, object] | None) -> bool:
    payload = dict((profile_transform_audit_run or {}).get("payload", {}))
    target = dict(payload.get("next_bounded_validation_target", {}))
    selected = [str(item) for item in target.get("selected_hypotheses", [])]
    return selected == ["H1", "H3"]


def _validation_rows_from_payload(payload: dict[str, object]) -> list[dict[str, object]]:
    validations = payload.get("validations", [])
    if isinstance(validations, list):
        return [dict(item) for item in validations if isinstance(item, dict)]
    return []


def _indexed_validation_rows(kind: str) -> tuple[list[dict[str, object]], str]:
    payload, path = _indexed_artifact_payload(kind)
    return _validation_rows_from_payload(payload), path


def _runtime_rows_by_candidate(
    *validation_groups: Sequence[dict[str, object]],
) -> dict[str, dict[str, object]]:
    rows: dict[str, dict[str, object]] = {}
    for group in validation_groups:
        for item in group:
            candidate_hex = _candidate_hex_from_entry(dict(item))
            if not candidate_hex:
                continue
            current = rows.get(candidate_hex)
            if current is None:
                rows[candidate_hex] = dict(item)
                continue
            current_agree = bool(current.get("compare_semantics_agree"))
            item_agree = bool(item.get("compare_semantics_agree"))
            current_has_prefix = bool(str(current.get("runtime_lhs_prefix_hex_10", "")).strip())
            item_has_prefix = bool(str(item.get("runtime_lhs_prefix_hex_10", "")).strip())
            if (item_agree, item_has_prefix) > (current_agree, current_has_prefix):
                rows[candidate_hex] = dict(item)
    return rows


def _trace_compare_metrics(trace: dict[str, object]) -> tuple[str, int, int]:
    rc4 = dict(trace.get("rc4", {})) if isinstance(trace.get("rc4"), dict) else {}
    compare_boundary = (
        dict(trace.get("compare_boundary", {}))
        if isinstance(trace.get("compare_boundary"), dict)
        else {}
    )
    offline_prefix = str(
        compare_boundary.get("raw_prefix_hex_10")
        or str(rc4.get("decrypt_prefix_hex", ""))[: len(TARGET_PREFIX) * 2]
    ).strip().lower()
    return (
        offline_prefix,
        int(compare_boundary.get("ci_exact_wchars", 0) or 0),
        int(compare_boundary.get("ci_distance5", 1 << 30) or (1 << 30)),
    )


def _transform_consistency_verdict(
    *,
    candidate_hex: str,
    trace: dict[str, object],
    runtime_entry: dict[str, object] | None,
) -> dict[str, object]:
    offline_prefix, offline_exact, offline_distance = _trace_compare_metrics(trace)
    if not runtime_entry:
        return {
            "candidate_hex": candidate_hex,
            "offline_prefix_hex_10": offline_prefix,
            "offline_ci_exact_wchars": offline_exact,
            "offline_ci_distance5": offline_distance,
            "runtime_prefix_hex_10": "",
            "runtime_ci_exact_wchars": None,
            "runtime_ci_distance5": None,
            "offline_runtime_prefix_agree_10": False,
            "offline_runtime_metrics_agree": False,
            "compare_semantics_agree": None,
            "first_unsupported_stage": "runtime_validation",
            "evidence_status": "missing_runtime_artifact",
        }

    runtime_prefix = str(runtime_entry.get("runtime_lhs_prefix_hex_10", "")).strip().lower()
    runtime_exact_raw = runtime_entry.get("runtime_ci_exact_wchars")
    runtime_distance_raw = runtime_entry.get("runtime_ci_distance5")
    runtime_exact = int(runtime_exact_raw) if runtime_exact_raw is not None else None
    runtime_distance = int(runtime_distance_raw) if runtime_distance_raw is not None else None
    prefix_agree = bool(runtime_prefix) and runtime_prefix == offline_prefix
    metrics_agree = runtime_exact == offline_exact and runtime_distance == offline_distance
    compare_agree = runtime_entry.get("compare_semantics_agree")

    if not runtime_prefix:
        first_unsupported_stage = "runtime_prefix"
        evidence_status = "missing_runtime_prefix"
    elif not prefix_agree:
        first_unsupported_stage = "rc4_output"
        evidence_status = "runtime_mismatch"
    elif not metrics_agree:
        first_unsupported_stage = "compare_metrics"
        evidence_status = "runtime_mismatch"
    elif compare_agree is False:
        first_unsupported_stage = "compare_semantics"
        evidence_status = "runtime_mismatch"
    else:
        first_unsupported_stage = ""
        evidence_status = "supported_by_runtime"

    return {
        "candidate_hex": candidate_hex,
        "offline_prefix_hex_10": offline_prefix,
        "offline_ci_exact_wchars": offline_exact,
        "offline_ci_distance5": offline_distance,
        "runtime_prefix_hex_10": runtime_prefix,
        "runtime_ci_exact_wchars": runtime_exact,
        "runtime_ci_distance5": runtime_distance,
        "offline_runtime_prefix_agree_10": prefix_agree,
        "offline_runtime_metrics_agree": metrics_agree,
        "compare_semantics_agree": compare_agree,
        "first_unsupported_stage": first_unsupported_stage,
        "evidence_status": evidence_status,
        "runtime_source": str(runtime_entry.get("stage", runtime_entry.get("frontier_role", ""))),
    }


def run_transform_trace_consistency_diagnostic(
    *,
    artifacts_dir: Path,
    runtime_validations: Sequence[dict[str, object]],
    transform_model: SamplereverseTransformModel,
    log: Any | None = None,
) -> dict[str, object]:
    _ = transform_model
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    h1_h3_rows, h1_h3_path = _indexed_validation_rows("h1_h3_boundary_validation_runtime")
    value_pool_rows, value_pool_path = _indexed_validation_rows("exact2_basin_value_pool_validation")
    rows_by_candidate = _runtime_rows_by_candidate(runtime_validations, h1_h3_rows, value_pool_rows)

    candidates: list[dict[str, object]] = []
    for candidate_hex in TRANSFORM_TRACE_CONSISTENCY_CANDIDATES:
        trace = trace_candidate_transform(candidate_hex)
        verdict = _transform_consistency_verdict(
            candidate_hex=candidate_hex,
            trace=trace,
            runtime_entry=rows_by_candidate.get(candidate_hex),
        )
        candidates.append(
            {
                "candidate_hex": candidate_hex,
                "trace": trace,
                "verdict": verdict,
            }
        )

    runtime_backed = [
        item for item in candidates if dict(item.get("verdict", {})).get("evidence_status") != "missing_runtime_artifact"
    ]
    baseline = next(
        (dict(item.get("verdict", {})) for item in candidates if item.get("candidate_hex") == TRANSFORM_TRACE_CONSISTENCY_CANDIDATES[0]),
        {},
    )
    mismatches = [
        dict(item.get("verdict", {}))
        for item in runtime_backed
        if dict(item.get("verdict", {})).get("evidence_status") == "runtime_mismatch"
    ]
    missing = [
        dict(item.get("verdict", {}))
        for item in candidates
        if dict(item.get("verdict", {})).get("evidence_status") in {"missing_runtime_artifact", "missing_runtime_prefix"}
    ]
    if mismatches:
        classification = "transform_mismatch_found"
        stop_reason = "offline transform trace diverges from runtime validation evidence"
    elif baseline.get("evidence_status") != "supported_by_runtime" or len(runtime_backed) < 3:
        classification = "evidence_insufficient"
        stop_reason = "not enough runtime-backed candidates to confirm transform consistency"
    else:
        classification = "transform_model_confirmed"
        stop_reason = "runtime-backed candidates agree with offline trace prefixes and metrics"

    payload: dict[str, object] = {
        "artifact_kind": "transform_trace_consistency",
        "profile": "samplereverse",
        "attempted": True,
        "classification": classification,
        "stop_reason": stop_reason,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(candidates),
        "runtime_backed_count": len(runtime_backed),
        "runtime_sources": {
            "current_run_validations": len(runtime_validations),
            "h1_h3_boundary_validation_runtime": h1_h3_path,
            "h1_h3_boundary_validation_runtime_count": len(h1_h3_rows),
            "exact2_basin_value_pool_validation": value_pool_path,
            "exact2_basin_value_pool_validation_count": len(value_pool_rows),
        },
        "decision": {
            "transform_mismatch_found": bool(classification == "transform_mismatch_found"),
            "transform_model_confirmed": bool(classification == "transform_model_confirmed"),
            "evidence_insufficient": bool(classification == "evidence_insufficient"),
            "minimal_transform_fix": (
                "inspect first_unsupported_stage and update the matching transform helper only"
                if classification == "transform_mismatch_found"
                else ""
            ),
            "next_bounded_action": (
                "stop local mutation and use a different bounded evidence source"
                if classification == "transform_model_confirmed"
                else "capture pre-RC4/Base64 runtime buffers with a bounded dynamic probe"
                if classification == "evidence_insufficient"
                else "repair transform/compare helper, then revalidate exact2"
            ),
        },
        "mismatches": mismatches,
        "missing_runtime_evidence": missing,
        "candidates": candidates,
        "promotable_validations": [],
    }
    output_path = artifacts_dir / TRANSFORM_TRACE_CONSISTENCY_FILE_NAME
    _write_json(output_path, payload)
    if log:
        log(f"transform trace consistency diagnostic wrote {output_path}")
    return {
        "result_path": str(output_path),
        "payload": payload,
        "validations": [],
        "promotable_validations": [],
    }


def run_h1_h3_boundary_validation(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log,
    baseline_exact: int = 2,
    baseline_distance: int = DEFAULT_BRIDGE_BASELINE_DISTANCE5,
) -> dict[str, object]:
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / H1_H3_BOUNDARY_VALIDATION_FILE_NAME
    entries = _h1_h3_boundary_validation_entries(transform_model)
    payload: dict[str, object] = {
        "artifact_kind": "h1_h3_boundary_validation",
        "profile": "samplereverse",
        "attempted": True,
        "classification": "h1_h3_boundary_validation_pending",
        "selected_hypotheses": ["H1", "H3"],
        "candidate_limit": H1_H3_BOUNDARY_CANDIDATE_LIMIT,
        "candidate_count": len(entries),
        "baseline_candidate": "78d540b49c59077041414141414141",
        "baseline_exact_wchars": int(baseline_exact),
        "baseline_distance5": int(baseline_distance),
        "candidate_generation": "fixed_hand_picked_contrast_set",
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "validation_required": True,
        "success_signal": "runtime_ci_exact_wchars > 2 or runtime_ci_distance5 < 246 with compare_semantics_agree=true",
        "validation_candidates": entries,
        "validations": [],
        "best_runtime_candidate": {},
        "promotable_validations": [],
        "improved_over_exact2": False,
    }
    _write_json(result_path, payload)

    validation_path: Path | None = None
    validations: list[dict[str, object]] = []
    if entries:
        validation_path, validations = validate_compare_aware_results(
            target=target,
            artifacts_dir=artifacts_dir / "validation",
            result_path=result_path,
            transform_model=transform_model,
            validate_top=len(entries),
            per_probe_timeout=per_probe_timeout,
            log=log,
            output_file_name=H1_H3_BOUNDARY_VALIDATION_FILE_NAME,
            compare_output_prefix="h1_h3_boundary_compare_aware",
        )

    compare_agree_validations = [
        item for item in validations if bool(item.get("compare_semantics_agree"))
    ]
    best_runtime_candidate = (
        sorted(compare_agree_validations, key=_runtime_validation_sort_key)[0]
        if compare_agree_validations
        else {}
    )
    promotable_validations = [
        item
        for item in validations
        if _exact2_basin_runtime_improved(
            item,
            baseline_exact=int(baseline_exact),
            baseline_distance=int(baseline_distance),
        )
    ]
    improved = bool(promotable_validations)
    payload.update(
        {
            "classification": (
                "h1_h3_boundary_contrast_improved"
                if improved
                else "h1_h3_boundary_contrast_exhausted_no_gain"
            ),
            "validated_count": len(validations),
            "validation_path": str(validation_path) if validation_path else "",
            "validations": validations,
            "best_runtime_candidate": best_runtime_candidate,
            "promotable_validations": promotable_validations,
            "improved_over_exact2": improved,
        }
    )
    _write_json(result_path, payload)
    return {
        "result_path": str(result_path),
        "validation_path": str(validation_path) if validation_path else "",
        "payload": payload,
        "validations": validations,
        "promotable_validations": promotable_validations,
    }


def _dynamic_compare_path_probe_entries(
    transform_model: SamplereverseTransformModel,
) -> list[dict[str, object]]:
    _ = transform_model
    entries: list[dict[str, object]] = []
    for idx, candidate_hex in enumerate(DYNAMIC_COMPARE_PATH_PROBE_CANDIDATES, 1):
        trace = trace_candidate_transform(candidate_hex)
        compare_boundary = dict(trace.get("compare_boundary", {})) if isinstance(trace, dict) else {}
        entries.append(
            {
                "label": f"dynamic_compare_path_probe_{idx}",
                "candidate_hex": candidate_hex,
                "cand8_hex": candidate_hex[:16],
                "ci_exact_wchars": int(compare_boundary.get("ci_exact_wchars", 0) or 0),
                "ci_distance5": int(compare_boundary.get("ci_distance5", 1 << 30) or (1 << 30)),
                "raw_distance10": int(compare_boundary.get("raw_distance10", 1 << 30) or (1 << 30)),
                "raw_prefix_hex": str(compare_boundary.get("raw_prefix_hex", "")),
                "raw_prefix_hex_64": str(compare_boundary.get("raw_prefix_hex_64", "")),
                "trace": trace,
                "probe_role": (
                    "exact2_baseline"
                    if idx == 1
                    else "near_suffix_control"
                    if idx == 2
                    else "frontier_control"
                ),
            }
        )
    return entries


def _runtime_probe_backed(validation: dict[str, object]) -> bool:
    return bool(
        str(validation.get("runtime_lhs_prefix_hex_10", "")).strip()
        or str(validation.get("runtime_lhs_prefix_hex", "")).strip()
    )


def _probe_point_statuses(validations: Sequence[dict[str, object]]) -> dict[str, str]:
    runtime_backed = [item for item in validations if _runtime_probe_backed(item)]
    has_target = any(str(item.get("runtime_rhs_prefix_hex", "")).strip() for item in runtime_backed)
    has_count = any(item.get("runtime_compare_count") not in (None, "") for item in runtime_backed)
    has_wide_target = any(
        str(item.get("runtime_rhs_prefix_hex", "")).lower().startswith(TARGET_PREFIX.hex())
        for item in runtime_backed
    )
    return {
        "raw_input": "available" if validations else "unavailable",
        "utf16le_payload": "inferred",
        "base64_material": "inferred",
        "rc4_input": "inferred",
        "rc4_key": "inferred",
        "pre_rc4_runtime_material": "unavailable",
        "post_rc4_compare_buffer": "available" if runtime_backed else "unavailable",
        "compare_target": "available" if has_target else "unavailable",
        "compare_length": "available" if has_count else "unavailable",
        "compare_unit": "available" if has_count and has_wide_target else "inferred",
    }


def _first_failing_wchar(validation: dict[str, object]) -> dict[str, object]:
    boundary = dict(validation.get("prefix_boundary", {}))
    deltas = boundary.get("wchar_deltas", [])
    if not isinstance(deltas, list):
        return {}
    for item in deltas:
        if not isinstance(item, dict):
            continue
        if not bool(item.get("exact_ci")):
            return {
                "index": item.get("index"),
                "raw_pair_hex": item.get("raw_pair_hex", ""),
                "target_pair_hex": item.get("target_pair_hex", ""),
                "distance": item.get("distance"),
            }
    return {}


def _dynamic_probe_candidate_result(validation: dict[str, object]) -> dict[str, object]:
    return {
        "candidate_hex": str(validation.get("candidate_hex", "")),
        "probe_role": str(validation.get("probe_role", "")),
        "runtime_backed": _runtime_probe_backed(validation),
        "runtime_exact_wchars": int(validation.get("runtime_ci_exact_wchars", 0) or 0),
        "runtime_distance5": int(validation.get("runtime_ci_distance5", 1 << 30) or (1 << 30)),
        "compare_semantics_agree": bool(validation.get("compare_semantics_agree")),
        "runtime_compare_buffer_preview": str(validation.get("runtime_lhs_prefix_hex", "")),
        "runtime_compare_target_preview": str(validation.get("runtime_rhs_prefix_hex", "")),
        "runtime_compare_length": validation.get("runtime_compare_count"),
        "runtime_compare_unit": "wchar" if validation.get("runtime_compare_count") == 5 else "inferred_wchar",
        "lhs_ptr": str(validation.get("runtime_lhs_ptr", "")),
        "rhs_ptr": str(validation.get("runtime_rhs_ptr", "")),
        "pre_rc4_material": "unavailable",
        "rc4_key_material": "inferred_from_offline_trace",
        "first_failing_wchar": _first_failing_wchar(validation),
        "evidence_explains_exact2_plateau": (
            "runtime compare buffer matches modeled post-RC4 bytes; plateau is first visible at the first nonmatching wchar"
            if _runtime_probe_backed(validation) and bool(validation.get("compare_semantics_agree"))
            else "runtime evidence unavailable or offline/runtime compare semantics disagree"
        ),
        "trace": validation.get("trace", {}),
    }


def run_dynamic_compare_path_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log,
) -> dict[str, object]:
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / DYNAMIC_COMPARE_PATH_PROBE_FILE_NAME
    entries = _dynamic_compare_path_probe_entries(transform_model)
    payload: dict[str, object] = {
        "artifact_kind": "dynamic_compare_path_probe",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(DYNAMIC_COMPARE_PATH_PROBE_CANDIDATES),
        "validation_candidates": entries,
        "promotable_validations": [],
    }
    _write_json(result_path, payload)

    validation_kwargs = {
        "target": target,
        "artifacts_dir": artifacts_dir / "validation",
        "result_path": result_path,
        "transform_model": transform_model,
        "validate_top": len(entries),
        "per_probe_timeout": per_probe_timeout,
        "log": log,
        "output_file_name": DYNAMIC_COMPARE_PATH_PROBE_FILE_NAME,
        "compare_output_prefix": "dynamic_compare_path_probe_compare",
        "capture_prefix_bytes": RUNTIME_PREFIX_BYTES,
    }
    try:
        validation_path, validations = validate_compare_aware_results(**validation_kwargs)
    except TypeError as exc:
        if "capture_prefix_bytes" not in str(exc):
            raise
        validation_kwargs.pop("capture_prefix_bytes", None)
        validation_path, validations = validate_compare_aware_results(**validation_kwargs)
    runtime_backed_count = sum(1 for item in validations if _runtime_probe_backed(item))
    probe_points = _probe_point_statuses(validations)
    complete = runtime_backed_count >= len(entries) and all(
        probe_points.get(key) == "available"
        for key in ("post_rc4_compare_buffer", "compare_target", "compare_length")
    )
    classification = (
        "dynamic_probe_complete"
        if complete
        else "dynamic_probe_partial"
        if runtime_backed_count
        else "dynamic_probe_unavailable"
    )
    findings = [
        "compare-site runtime LHS/RHS/count capture is available"
        if runtime_backed_count
        else "compare-site runtime capture is unavailable",
        "pre-RC4/Base64/RC4 key material is not directly captured by the current compare-site hook",
    ]
    if probe_points.get("compare_target") == "available" and probe_points.get("compare_length") == "available":
        findings.append("compare target and compare length are runtime-backed at the compare call")

    payload.update(
        {
            "classification": classification,
            "runtime_backed_count": runtime_backed_count,
            "validation_path": str(validation_path),
            "probe_points": probe_points,
            "candidate_results": [_dynamic_probe_candidate_result(item) for item in validations],
            "findings": findings,
            "compare_path_assessment": {
                "rc4_key_fully_confirmed": False,
                "rc4_input_confirmed_as_base64_ascii_bytes": False,
                "compare_target_confirmed_as_flag_prefix": probe_points.get("compare_target") == "available",
                "compare_start_byte_zero_supported": bool(runtime_backed_count),
                "offset_prefix_skip_stride_or_null_stop_evidence": (
                    "none_observed_at_compare_site" if runtime_backed_count else "unavailable"
                ),
                "first_runtime_failure_after_exact2": _first_failing_wchar(validations[0]) if validations else {},
            },
            "next_bounded_action": (
                "move to lower-level dynamic instrumentation/manual reversing for pre-RC4 or key material"
                if classification == "dynamic_probe_complete"
                else "repair compare-site runtime capture before continuing local compare-aware search"
            ),
            "promotable_validations": [],
        }
    )
    _write_json(result_path, payload)
    if log:
        log(f"dynamic compare-path probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "validation_path": str(validation_path),
        "payload": payload,
        "validations": validations,
        "promotable_validations": [],
    }


def _material_hex_prefix(value: bytes, min_prefix: int = 16) -> str:
    if not value:
        return ""
    return value[: min(len(value), max(1, min_prefix))].hex()


def _pre_rc4_expected_materials(candidate_hex: str) -> dict[str, object]:
    normalized = str(candidate_hex).strip().lower()
    trace = trace_candidate_transform(normalized)
    candidate = bytes.fromhex(normalized)
    expanded_hex = str(dict(trace.get("nibble_expansion", {})).get("expanded_hex", ""))
    utf16_hex = str(dict(trace.get("utf16_payload", {})).get("raw_hex", ""))
    base64_text = str(dict(trace.get("base64_boundary", {})).get("base64_prefix", ""))
    base64_bytes = base64_text.encode("ascii", errors="ignore")
    rc4_ksa_key = base64_text.encode("utf-16le")[: len(base64_text)]
    rc4_output = bytes.fromhex(str(dict(trace.get("rc4", {})).get("decrypt_prefix_hex", "")))
    encrypted_const = _samplereverse_enc_const()[: len(rc4_output)]
    keystream = bytes(left ^ right for left, right in zip(encrypted_const, rc4_output))

    materials = [
        {
            "name": "raw_input",
            "hex": candidate.hex(),
            "prefix_hex": _material_hex_prefix(candidate, 8),
            "length": len(candidate),
            "description": "raw candidate bytes",
        },
        {
            "name": "expanded_bytes",
            "hex": expanded_hex,
            "prefix_hex": expanded_hex[:32],
            "length": len(bytes.fromhex(expanded_hex)) if expanded_hex else 0,
            "description": "nibble-expanded candidate bytes",
        },
        {
            "name": "utf16le_payload",
            "hex": utf16_hex,
            "prefix_hex": utf16_hex[:32],
            "length": len(bytes.fromhex(utf16_hex)) if utf16_hex else 0,
            "description": "expanded bytes interleaved as UTF-16LE low bytes",
        },
        {
            "name": "base64_ascii",
            "hex": base64_bytes.hex(),
            "prefix_hex": _material_hex_prefix(base64_bytes),
            "length": len(base64_bytes),
            "description": "standard Base64 text before UTF-16LE key derivation",
        },
        {
            "name": "rc4_ksa_key",
            "hex": rc4_ksa_key.hex(),
            "prefix_hex": _material_hex_prefix(rc4_ksa_key),
            "length": len(rc4_ksa_key),
            "description": "Base64 text encoded UTF-16LE and truncated to Base64 char count",
        },
        {
            "name": "rc4_encrypted_const",
            "hex": encrypted_const.hex(),
            "prefix_hex": _material_hex_prefix(encrypted_const),
            "length": len(encrypted_const),
            "description": "static encrypted const consumed by RC4 keystream xor",
        },
        {
            "name": "rc4_output",
            "hex": rc4_output.hex(),
            "prefix_hex": _material_hex_prefix(rc4_output),
            "length": len(rc4_output),
            "description": "modeled post-RC4 output prefix",
        },
        {
            "name": "compare_buffer",
            "hex": rc4_output[:RUNTIME_PREFIX_BYTES].hex(),
            "prefix_hex": rc4_output[: len(TARGET_PREFIX)].hex(),
            "length": min(len(rc4_output), RUNTIME_PREFIX_BYTES),
            "description": "post-RC4 buffer used as compare LHS",
        },
        {
            "name": "compare_target",
            "hex": TARGET_PREFIX.hex(),
            "prefix_hex": TARGET_PREFIX.hex(),
            "length": len(TARGET_PREFIX),
            "description": "wide flag{ compare RHS",
        },
    ]
    return {
        "candidate_hex": normalized,
        "trace": trace,
        "materials": materials,
        "base64_text": base64_text,
        "rc4_ksa_key_hex": rc4_ksa_key.hex(),
        "rc4_encrypted_const_hex": encrypted_const.hex(),
        "rc4_output_hex": rc4_output.hex(),
        "rc4_keystream_hex": keystream.hex(),
    }


def _pre_rc4_probe_entries(transform_model: SamplereverseTransformModel) -> list[dict[str, object]]:
    _ = transform_model
    entries: list[dict[str, object]] = []
    roles = ("exact2_baseline", "near_suffix_control", "frontier_control")
    for idx, candidate_hex in enumerate(PRE_RC4_MATERIAL_PROBE_CANDIDATES, 1):
        expected = _pre_rc4_expected_materials(candidate_hex)
        trace = dict(expected.get("trace", {}))
        compare_boundary = dict(trace.get("compare_boundary", {}))
        entries.append(
            {
                "label": f"pre_rc4_material_probe_{idx}",
                "candidate_hex": candidate_hex,
                "cand8_hex": candidate_hex[:16],
                "probe_role": roles[idx - 1],
                "ci_exact_wchars": int(compare_boundary.get("ci_exact_wchars", 0) or 0),
                "ci_distance5": int(compare_boundary.get("ci_distance5", 1 << 30) or (1 << 30)),
                "raw_prefix_hex": str(compare_boundary.get("raw_prefix_hex", "")),
                "raw_prefix_hex_64": str(compare_boundary.get("raw_prefix_hex_64", "")),
                "expected_materials": expected,
            }
        )
    return entries


def _match_statuses(matches: Sequence[dict[str, object]]) -> dict[str, str]:
    by_name = {str(item.get("material", "")): str(item.get("status", "")) for item in matches}

    def status(name: str) -> str:
        return "available" if by_name.get(name) == "available" else "unavailable"

    return {
        "raw_input": status("raw_input"),
        "expanded_bytes": status("expanded_bytes"),
        "utf16le_payload": status("utf16le_payload"),
        "base64_material": status("base64_ascii"),
        "rc4_ksa_key": status("rc4_ksa_key"),
        "rc4_encrypted_const": status("rc4_encrypted_const"),
        "rc4_output": status("rc4_output"),
        "compare_buffer": status("compare_buffer"),
    }


def _aggregate_pre_rc4_probe_points(candidate_results: Sequence[dict[str, object]]) -> dict[str, str]:
    keys = (
        "raw_input",
        "expanded_bytes",
        "utf16le_payload",
        "base64_material",
        "rc4_ksa_key",
        "rc4_encrypted_const",
        "rc4_output",
        "compare_buffer",
    )
    return {
        key: (
            "available"
            if any(dict(item.get("probe_points", {})).get(key) == "available" for item in candidate_results)
            else "unavailable"
        )
        for key in keys
    }


def _availability_status(
    *,
    direct_key: str,
    fallback_key: str,
    probe_points: dict[str, str],
    runtime_backed_count: int,
) -> str:
    if probe_points.get(direct_key) == "available":
        return "confirmed"
    if probe_points.get(fallback_key) == "available":
        return "inferred"
    if runtime_backed_count:
        return "unknown"
    return "unknown"


def _expected_material_map(expected: dict[str, object]) -> dict[str, str]:
    materials = expected.get("materials", [])
    if not isinstance(materials, list):
        return {}
    return {
        str(item.get("name", "")): str(item.get("hex", "")).strip().lower()
        for item in materials
        if isinstance(item, dict) and str(item.get("name", ""))
    }


def _match_by_material(matches: Sequence[dict[str, object]], material: str) -> dict[str, object]:
    return next((dict(item) for item in matches if str(item.get("material", "")) == material), {})


def _runtime_match_hex(matches: Sequence[dict[str, object]], material: str) -> str:
    match = _match_by_material(matches, material)
    if str(match.get("status", "")) != "available":
        return ""
    return str(match.get("preview_hex", "")).strip().lower()


def _safe_decode_material(hex_text: str, encoding: str) -> str:
    raw = _hex_to_bytes(hex_text)
    if not raw:
        return ""
    try:
        return raw.decode(encoding, errors="replace").replace("\x00", "")
    except Exception:
        return ""


def _material_preview_agrees(offline_hex: str, runtime_hex: str) -> bool | None:
    offline = str(offline_hex or "").strip().lower()
    runtime = str(runtime_hex or "").strip().lower()
    if not offline or not runtime:
        return None
    compare_len = min(len(offline), len(runtime))
    return bool(compare_len and offline[:compare_len] == runtime[:compare_len])


def _runtime_offline_agreement_row(
    *,
    candidate_hex: str,
    expected: dict[str, object],
    matches: Sequence[dict[str, object]],
) -> dict[str, object]:
    material_map = _expected_material_map(expected)
    offline_utf16_hex = material_map.get("utf16le_payload", "")
    offline_base64_hex = material_map.get("base64_ascii", "")
    offline_rc4_hex = material_map.get("rc4_output", "")
    runtime_utf16_hex = _runtime_match_hex(matches, "utf16le_payload")
    runtime_base64_hex = _runtime_match_hex(matches, "base64_ascii")
    runtime_rc4_hex = _runtime_match_hex(matches, "rc4_output")
    utf16_agree = _material_preview_agrees(offline_utf16_hex, runtime_utf16_hex)
    base64_agree = _material_preview_agrees(offline_base64_hex, runtime_base64_hex)
    rc4_agree = _material_preview_agrees(offline_rc4_hex, runtime_rc4_hex)
    first_divergence_stage = ""
    if utf16_agree is False:
        first_divergence_stage = "utf16"
    elif base64_agree is False:
        first_divergence_stage = "base64"
    elif rc4_agree is False:
        first_divergence_stage = "rc4"
    elif any(value is None for value in (utf16_agree, base64_agree, rc4_agree)):
        first_divergence_stage = "unknown"
    return {
        "candidate_hex": candidate_hex,
        "offline_utf16_hex": offline_utf16_hex,
        "runtime_utf16_hex": runtime_utf16_hex,
        "utf16_agree": utf16_agree,
        "offline_base64_ascii": _safe_decode_material(offline_base64_hex, "ascii"),
        "runtime_base64_ascii": _safe_decode_material(runtime_base64_hex, "ascii"),
        "base64_agree": base64_agree,
        "offline_rc4_hex": offline_rc4_hex,
        "runtime_rc4_hex": runtime_rc4_hex,
        "rc4_agree": rc4_agree,
        "first_divergence_stage": first_divergence_stage,
    }


def _latest_producer_material_previews() -> dict[str, dict[str, str]]:
    payload, _ = _indexed_artifact_payload("compare_producer_trace_probe")
    out: dict[str, dict[str, str]] = {}
    results = payload.get("candidate_results", [])
    if not isinstance(results, list):
        return out
    for item in results:
        if not isinstance(item, dict):
            continue
        candidate_hex = str(item.get("candidate_hex", "")).strip().lower()
        trace_map = item.get("producer_trace_map", {})
        if not candidate_hex or not isinstance(trace_map, dict):
            continue
        producer = trace_map.get("producer_return_site", {})
        if not isinstance(producer, dict):
            continue
        out[candidate_hex] = {
            "producer_eax_preview_hex": str(producer.get("eax_preview_hex", "")).strip().lower(),
            "producer_lhs_slot_preview_hex": str(producer.get("lhs_slot_preview_hex", "")).strip().lower(),
        }
    return out


def _hex_relation(left_hex: str, right_hex: str) -> str:
    left = str(left_hex or "").strip().lower()
    right = str(right_hex or "").strip().lower()
    if not left or not right:
        return "no_match"
    if left == right:
        return "exact"
    if left.startswith(right) or right.startswith(left):
        return "prefix"
    if left in right or right in left:
        return "slice"
    return "no_match"


def _best_relation(*relations: str) -> str:
    for candidate in ("exact", "prefix", "slice"):
        if candidate in relations:
            return candidate
    return "no_match"


def _producer_relation_row(
    *,
    candidate_hex: str,
    expected: dict[str, object],
    matches: Sequence[dict[str, object]],
    producer_previews: dict[str, dict[str, str]],
) -> dict[str, object]:
    runtime_rc4_hex = _runtime_match_hex(matches, "rc4_output")
    if not runtime_rc4_hex:
        runtime_rc4_hex = str(expected.get("rc4_output_hex", "")).strip().lower()
    producer = producer_previews.get(candidate_hex, {})
    eax_hex = str(producer.get("producer_eax_preview_hex", "")).strip().lower()
    lhs_hex = str(producer.get("producer_lhs_slot_preview_hex", "")).strip().lower()
    eax_relation = _hex_relation(runtime_rc4_hex, eax_hex)
    lhs_relation = _hex_relation(runtime_rc4_hex, lhs_hex)
    return {
        "candidate_hex": candidate_hex,
        "utf16_material": _runtime_match_hex(matches, "utf16le_payload"),
        "base64_output": _runtime_match_hex(matches, "base64_ascii"),
        "rc4_output": runtime_rc4_hex,
        "producer_eax": eax_hex,
        "producer_lhs_slot": lhs_hex,
        "rc4_to_producer_eax_relation": eax_relation,
        "rc4_to_producer_lhs_slot_relation": lhs_relation,
        "rc4_to_producer_relation": _best_relation(eax_relation, lhs_relation),
    }


def _first_material_divergence(agreement_table: Sequence[dict[str, object]]) -> str:
    for stage in ("utf16", "base64", "rc4"):
        if any(str(item.get("first_divergence_stage", "")) == stage for item in agreement_table):
            return stage
    return ""


def _classify_pre_rc4_material_capture(
    *,
    runtime_backed_count: int,
    agreement_table: Sequence[dict[str, object]],
    relation_table: Sequence[dict[str, object]],
) -> str:
    if runtime_backed_count == 0:
        return "material_capture_unreliable"
    divergence = _first_material_divergence(agreement_table)
    if divergence:
        return f"{divergence}_diverges"
    required = ("utf16_agree", "base64_agree", "rc4_agree")
    if not agreement_table or any(item.get(key) is not True for item in agreement_table for key in required):
        return "material_capture_partial"
    relations = {str(item.get("rc4_to_producer_relation", "")) for item in relation_table}
    if relations & {"exact", "prefix", "slice"}:
        return "needs_compare_path_discovery"
    if any(item.get("producer_eax") or item.get("producer_lhs_slot") for item in relation_table):
        return "rc4_not_producer_buffer"
    return "material_chain_agrees"


def _pre_rc4_next_bounded_action(classification: str) -> str:
    return {
        "material_chain_agrees": "use confirmed material chain to choose the next compare-path discovery target",
        "needs_compare_path_discovery": "discover the alternate or skipped compare path that consumes the producer-side transformed buffer",
        "rc4_not_producer_buffer": "choose a narrower producer hook to explain where RC4 output is copied or transformed next",
        "utf16_diverges": "stop candidate search and correct the UTF-16LE material model",
        "base64_diverges": "stop candidate search and correct the Base64 material model",
        "rc4_diverges": "stop candidate search and correct the RC4 key/input/output model",
        "material_capture_partial": "add a narrower material hook or bounded Base64/RC4 breakpoint fallback",
        "material_capture_unreliable": "repair material capture reliability before expanding search",
    }.get(classification, "inspect pre-RC4 material probe artifact")


def _exact2_failure_trace_from_expected(expected: dict[str, object]) -> dict[str, object]:
    trace = dict(expected.get("trace", {}))
    compare_boundary = dict(trace.get("compare_boundary", {}))
    deltas = compare_boundary.get("wchar_deltas", [])
    failing = {}
    if isinstance(deltas, list):
        for item in deltas:
            if isinstance(item, dict) and int(item.get("index", -1) or -1) == 2:
                failing = item
                break
    output_offsets = [4, 5]
    encrypted_const = bytes.fromhex(str(expected.get("rc4_encrypted_const_hex", "")))
    rc4_output = bytes.fromhex(str(expected.get("rc4_output_hex", "")))
    keystream = bytes.fromhex(str(expected.get("rc4_keystream_hex", "")))
    return {
        "wchar_index": 2,
        "runtime_word": str(failing.get("raw_pair_hex", rc4_output[4:6].hex() if len(rc4_output) >= 6 else "")),
        "target_word": str(failing.get("target_pair_hex", TARGET_PREFIX[4:6].hex())),
        "rc4_output_offsets": output_offsets,
        "encrypted_const_bytes": encrypted_const[4:6].hex(),
        "keystream_bytes": keystream[4:6].hex(),
        "rc4_output_bytes": rc4_output[4:6].hex(),
        "base64_key_dependency": {
            "model": "Base64(UTF-16LE expanded candidate) -> UTF-16LE bytes truncated to Base64 char count -> RC4 KSA key",
            "base64_preview": str(expected.get("base64_text", ""))[:48],
            "rc4_ksa_key_length": len(bytes.fromhex(str(expected.get("rc4_ksa_key_hex", "")))),
            "candidate_byte_dependencies": "RC4 KSA diffuses the full Base64-derived key; byte-local dependency requires a follow-up constraint diagnostic after runtime key confirmation.",
        },
    }


def _pe_sections_for_rva_mapping(data: bytes) -> list[dict[str, int]]:
    try:
        pe_offset = int.from_bytes(data[0x3C:0x40], "little")
        if data[pe_offset:pe_offset + 4] != b"PE\0\0":
            return []
        number_of_sections = int.from_bytes(data[pe_offset + 6:pe_offset + 8], "little")
        optional_header_size = int.from_bytes(data[pe_offset + 20:pe_offset + 22], "little")
        section_offset = pe_offset + 24 + optional_header_size
    except Exception:
        return []
    sections: list[dict[str, int]] = []
    for idx in range(max(0, number_of_sections)):
        base = section_offset + idx * 40
        if base + 40 > len(data):
            break
        virtual_size = int.from_bytes(data[base + 8:base + 12], "little")
        virtual_address = int.from_bytes(data[base + 12:base + 16], "little")
        raw_size = int.from_bytes(data[base + 16:base + 20], "little")
        raw_pointer = int.from_bytes(data[base + 20:base + 24], "little")
        sections.append(
            {
                "virtual_size": virtual_size,
                "virtual_address": virtual_address,
                "raw_size": raw_size,
                "raw_pointer": raw_pointer,
            }
        )
    return sections


def _file_offset_to_rva(file_offset: int, sections: Sequence[dict[str, int]]) -> int | None:
    for section in sections:
        raw_pointer = int(section.get("raw_pointer", 0))
        raw_size = int(section.get("raw_size", 0))
        virtual_address = int(section.get("virtual_address", 0))
        virtual_size = int(section.get("virtual_size", 0))
        span = max(raw_size, virtual_size, 1)
        if raw_pointer <= file_offset < raw_pointer + span:
            return virtual_address + (file_offset - raw_pointer)
    return file_offset if file_offset >= 0 else None


def _rva_to_file_offset(rva: int, sections: Sequence[dict[str, int]]) -> int | None:
    for section in sections:
        raw_pointer = int(section.get("raw_pointer", 0))
        raw_size = int(section.get("raw_size", 0))
        virtual_address = int(section.get("virtual_address", 0))
        virtual_size = int(section.get("virtual_size", 0))
        span = max(raw_size, virtual_size, 1)
        if virtual_address <= rva < virtual_address + span:
            return raw_pointer + (rva - virtual_address)
    return rva if rva >= 0 else None


def _first_file_offset(data: bytes, needle: bytes) -> int | None:
    if not needle:
        return None
    found = data.find(needle)
    return found if found >= 0 else None


def _static_point(
    *,
    kind: str,
    name: str,
    module_offset: int | None,
    confidence: str,
    evidence: Sequence[str],
    hook_kind: str = "memory_access",
    hookable: bool | None = None,
    size: int = 1,
) -> dict[str, object]:
    is_hookable = bool(module_offset is not None) if hookable is None else bool(hookable)
    return {
        "kind": kind,
        "name": name,
        "address": f"module+0x{module_offset:x}" if module_offset is not None else "",
        "module_offset": module_offset,
        "confidence": confidence,
        "evidence": list(evidence),
        "hook_kind": hook_kind,
        "hookable": is_hookable,
        "size": max(1, int(size)),
    }


def _format_offset(value: object) -> str:
    if isinstance(value, int):
        return f"0x{value:x}"
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        parsed = int(text, 16) if text.lower().startswith("0x") else int(text)
    except ValueError:
        return ""
    return f"0x{parsed:x}"


def _static_point_module_offset(value: object) -> int | None:
    if isinstance(value, int):
        return value
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return int(text, 16) if text.lower().startswith("0x") else int(text)
    except ValueError:
        return None


def _base64_rc4_static_points(target: Path) -> dict[str, list[dict[str, object]]]:
    groups: dict[str, list[dict[str, object]]] = {
        "utf16le": [],
        "base64": [],
        "rc4_ksa": [],
        "rc4_prga": [],
        "encrypted_const": [],
    }
    try:
        data = target.read_bytes()
    except OSError as exc:
        reason = f"target_read_failed:{exc}"
        for key in groups:
            groups[key].append(
                _static_point(
                    kind=key,
                    name=f"{key}_unavailable",
                    module_offset=None,
                    confidence="low",
                    evidence=[reason],
                    hookable=False,
                )
            )
        return groups

    sections = _pe_sections_for_rva_mapping(data)
    base64_alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    base64_offset = _first_file_offset(data, base64_alphabet)
    if base64_offset is not None:
        rva = _file_offset_to_rva(base64_offset, sections)
        groups["base64"].append(
            _static_point(
                kind="base64",
                name="standard_base64_alphabet",
                module_offset=rva,
                confidence="high",
                evidence=[f"standard alphabet table file_offset=0x{base64_offset:x}"],
                size=len(base64_alphabet),
            )
        )
    else:
        groups["base64"].append(
            _static_point(
                kind="base64",
                name="standard_base64_alphabet_unavailable",
                module_offset=None,
                confidence="low",
                evidence=["standard Base64 alphabet table not found in PE bytes"],
                hookable=False,
            )
        )

    encrypted_const = _samplereverse_enc_const()
    const_probe = encrypted_const[: min(16, len(encrypted_const))]
    const_offset = _first_file_offset(data, const_probe)
    if const_offset is not None:
        rva = _file_offset_to_rva(const_offset, sections)
        groups["encrypted_const"].append(
            _static_point(
                kind="encrypted_const",
                name="modeled_rc4_encrypted_const",
                module_offset=rva,
                confidence="high",
                evidence=[f"modeled encrypted const prefix file_offset=0x{const_offset:x}"],
                size=min(64, len(encrypted_const)),
            )
        )
    else:
        groups["encrypted_const"].append(
            _static_point(
                kind="encrypted_const",
                name="modeled_rc4_encrypted_const_unavailable",
                module_offset=None,
                confidence="low",
                evidence=["modeled encrypted const prefix not found in PE bytes"],
                hookable=False,
            )
        )

    groups["utf16le"].append(
        _static_point(
            kind="utf16le",
            name="utf16le_expansion_site_unresolved",
            module_offset=None,
            confidence="low",
            evidence=["no stable UTF-16LE construction instruction signature available from current artifacts"],
            hookable=False,
        )
    )
    groups["rc4_ksa"].append(
        _static_point(
            kind="rc4_ksa",
            name="rc4_ksa_site_unresolved",
            module_offset=None,
            confidence="low",
            evidence=["no stable RC4 KSA code signature available from current artifacts"],
            hookable=False,
        )
    )
    groups["rc4_prga"].append(
        _static_point(
            kind="rc4_prga",
            name="rc4_prga_site_unresolved",
            module_offset=None,
            confidence="low",
            evidence=["no stable RC4 PRGA code signature available from current artifacts"],
            hookable=False,
        )
    )
    return groups


def _discovery_point_from_static_point(point: dict[str, object]) -> dict[str, object]:
    module_offset = _static_point_module_offset(point.get("module_offset"))
    hookable = bool(point.get("hookable")) and module_offset is not None
    hook_kind = str(point.get("hook_kind", "") or "")
    instruction_confirmed = hookable and hook_kind == "interceptor"
    classification = (
        "hookable_and_instruction_confirmed"
        if instruction_confirmed
        else "hookable_but_unconfirmed"
        if hookable
        else "found_but_not_hookable"
    )
    evidence = [str(value) for value in point.get("evidence", []) if value is not None] if isinstance(point.get("evidence"), list) else []
    if hookable and not instruction_confirmed:
        evidence = [*evidence, f"hook_kind={hook_kind or 'unknown'} is not an instruction-level interceptor"]
    return {
        "kind": str(point.get("kind", "")),
        "name": str(point.get("name", "")),
        "module_offset": _format_offset(module_offset),
        "rva": _format_offset(module_offset),
        "function": "",
        "instruction": _format_offset(module_offset) if instruction_confirmed else "",
        "hookable": hookable,
        "instruction_confirmed": instruction_confirmed,
        "confidence": str(point.get("confidence", "low") or "low"),
        "evidence": evidence,
        "classification": classification,
        "candidate_dependent": bool(point.get("candidate_dependent")),
        "connects_to_compare_lhs": bool(point.get("connects_to_compare_lhs")),
        "connects_to_transform_chain": bool(point.get("connects_to_transform_chain")),
    }


def _compare_producer_discovery_points(static_audit: dict[str, object]) -> list[dict[str, object]]:
    points: list[dict[str, object]] = []
    audit_classification = str(static_audit.get("classification", "") or "")
    next_hook_points = static_audit.get("next_hook_points", [])
    if not isinstance(next_hook_points, list):
        next_hook_points = []
    for item in next_hook_points:
        if not isinstance(item, dict):
            continue
        module_offset = _static_point_module_offset(item.get("module_offset"))
        if module_offset is None:
            continue
        name = str(item.get("name") or "compare_producer")
        points.append(
            {
                "kind": "compare_producer",
                "name": name,
                "module_offset": _format_offset(module_offset),
                "rva": _format_offset(module_offset),
                "function": "",
                "instruction": _format_offset(module_offset),
                "hookable": audit_classification == "static_anchor_confirmed",
                "confidence": "high" if audit_classification == "static_anchor_confirmed" else "medium",
                "evidence": [
                    f"compare_stack_static_audit={audit_classification or 'unknown'}",
                    str(item.get("evidence", "") or f"next_hook_point={name}"),
                ],
                "classification": (
                    "hookable_and_instruction_confirmed"
                    if audit_classification == "static_anchor_confirmed"
                    else "hookable_but_unconfirmed"
                ),
            }
        )
    return points


def _base64_rc4_static_discovery_by_kind(points: Sequence[dict[str, object]]) -> dict[str, dict[str, int]]:
    by_kind: dict[str, dict[str, int]] = {}
    for point in points:
        kind = str(point.get("kind", "") or "unknown")
        entry = by_kind.setdefault(kind, {"count": 0, "hookable_count": 0, "instruction_confirmed_count": 0})
        entry["count"] += 1
        if bool(point.get("hookable")):
            entry["hookable_count"] += 1
        if str(point.get("classification", "")) == "hookable_and_instruction_confirmed":
            entry["instruction_confirmed_count"] += 1
    return by_kind


def _base64_rc4_static_discovery_classification(points: Sequence[dict[str, object]]) -> str:
    hookable = [point for point in points if bool(point.get("hookable"))]
    instruction_confirmed = [
        point
        for point in hookable
        if str(point.get("classification", "")) == "hookable_and_instruction_confirmed"
    ]
    semantic_records = [
        _semantic_record_from_material_hook_candidate(point)
        for point in instruction_confirmed
        if str(point.get("kind", "")) in BASE64_RC4_BREAKPOINT_READY_KINDS
    ]
    if compute_breakpoint_probe_allowed(semantic_records):
        return "breakpoint_probe_ready"
    if instruction_confirmed:
        return "hookable_points_found"
    if hookable:
        return "manual_disassembly_required"
    return "static_point_discovery_failed"


def _base64_rc4_static_discovery_next_action(classification: str) -> str:
    if classification == "breakpoint_probe_ready":
        return "rerun bounded Base64/RC4 breakpoint probe with instruction-confirmed static points"
    if classification == "hookable_points_found":
        return "use compare-producer hook evidence to narrow manual Base64/RC4 disassembly before rerunning breakpoint probe"
    if classification == "manual_disassembly_required":
        return "confirm the ambiguous Base64/RC4 offsets in IDA/x64dbg before rerunning breakpoint probe"
    return "manual IDA/x64dbg static point discovery is required; automated scan found zero hookable Base64/RC4 points"


def _discovery_point_sort_key(point: dict[str, object]) -> tuple[int, int, str]:
    classification = str(point.get("classification", ""))
    kind = str(point.get("kind", ""))
    return (
        0 if classification == "hookable_and_instruction_confirmed" else 1,
        0 if kind in BASE64_RC4_BREAKPOINT_READY_KINDS else 1,
        kind,
    )


def _breakpoint_static_points_from_discovery_payload(payload: dict[str, object]) -> dict[str, list[dict[str, object]]]:
    if not _base64_rc4_static_discovery_allows_breakpoint(payload):
        return {}
    static_points = payload.get("breakpoint_static_points", {})
    return static_points if isinstance(static_points, dict) else {}


def run_base64_rc4_static_point_discovery(
    *,
    target: Path,
    artifacts_dir: Path,
    log=None,
    static_points: dict[str, list[dict[str, object]]] | None = None,
) -> dict[str, object]:
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / BASE64_RC4_STATIC_POINT_DISCOVERY_FILE_NAME
    source_static_points = static_points if static_points is not None else _base64_rc4_static_points(target)
    points: list[dict[str, object]] = []
    for values in source_static_points.values():
        if not isinstance(values, list):
            continue
        for item in values:
            if isinstance(item, dict):
                points.append(_discovery_point_from_static_point(item))
    static_audit = _compare_stack_static_audit(target)
    points.extend(_compare_producer_discovery_points(static_audit))
    points.sort(key=_discovery_point_sort_key)
    classification = _base64_rc4_static_discovery_classification(points)
    instruction_confirmed_material = {
        str(point.get("kind", ""))
        for point in points
        if bool(point.get("hookable"))
        and str(point.get("classification", "")) == "hookable_and_instruction_confirmed"
        and str(point.get("kind", "")) in BASE64_RC4_BREAKPOINT_READY_KINDS
        and compute_breakpoint_probe_allowed([_semantic_record_from_material_hook_candidate(point)])
    }
    breakpoint_static_points: dict[str, list[dict[str, object]]] = {}
    if instruction_confirmed_material:
        for kind, values in source_static_points.items():
            if str(kind) not in instruction_confirmed_material or not isinstance(values, list):
                continue
            breakpoint_static_points[str(kind)] = [
                dict(item)
                for item in values
                if isinstance(item, dict)
                and bool(item.get("hookable"))
                and str(item.get("hook_kind", "")) == "interceptor"
                and _static_point_module_offset(item.get("module_offset")) is not None
            ]
    payload: dict[str, object] = {
        "artifact_kind": "base64_rc4_static_point_discovery",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "classification": classification,
        "hookable_count": sum(1 for point in points if bool(point.get("hookable"))),
        "instruction_confirmed_count": sum(
            1 for point in points if str(point.get("classification", "")) == "hookable_and_instruction_confirmed"
        ),
        "by_kind": _base64_rc4_static_discovery_by_kind(points),
        "best_points": points[:8],
        "points": points,
        "static_audit": static_audit,
        "static_point_summary": _breakpoint_static_point_summary(source_static_points),
        "breakpoint_probe_allowed": classification == "breakpoint_probe_ready"
        and bool(instruction_confirmed_material),
        "breakpoint_static_points": breakpoint_static_points,
        "next_bounded_action": _base64_rc4_static_discovery_next_action(classification),
        "promotable_validations": [],
    }
    _write_json(result_path, payload)
    if log:
        log(f"Base64/RC4 static point discovery wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "promotable_validations": [],
    }


def _breakpoint_probe_entries(transform_model: SamplereverseTransformModel) -> list[dict[str, object]]:
    _ = transform_model
    roles = ("exact2_baseline", "near_suffix_control", "frontier_control")
    entries: list[dict[str, object]] = []
    for idx, candidate_hex in enumerate(BASE64_RC4_BREAKPOINT_PROBE_CANDIDATES, 1):
        expected = _pre_rc4_expected_materials(candidate_hex)
        trace = dict(expected.get("trace", {}))
        compare_boundary = dict(trace.get("compare_boundary", {}))
        entries.append(
            {
                "label": f"base64_rc4_breakpoint_probe_{idx}",
                "candidate_hex": candidate_hex,
                "cand8_hex": candidate_hex[:16],
                "probe_role": roles[idx - 1],
                "ci_exact_wchars": int(compare_boundary.get("ci_exact_wchars", 0) or 0),
                "ci_distance5": int(compare_boundary.get("ci_distance5", 1 << 30) or (1 << 30)),
                "expected_materials": expected,
            }
        )
    return entries


def _aggregate_breakpoint_hook_results(candidate_results: Sequence[dict[str, object]]) -> dict[str, str]:
    keys = (
        "utf16le_payload",
        "base64_input",
        "base64_output",
        "rc4_key",
        "rc4_input",
        "rc4_output",
        "compare_buffer",
    )
    out: dict[str, str] = {}
    for key in keys:
        values = [
            str(dict(item.get("hook_results", {})).get(key, "unavailable"))
            for item in candidate_results
            if isinstance(item.get("hook_results"), dict)
        ]
        if "available" in values:
            out[key] = "available"
        elif "inferred" in values:
            out[key] = "inferred"
        else:
            out[key] = "unavailable"
    return out


def _breakpoint_static_point_summary(static_points: dict[str, list[dict[str, object]]]) -> dict[str, dict[str, int]]:
    summary: dict[str, dict[str, int]] = {}
    for kind, values in static_points.items():
        points = [item for item in values if isinstance(item, dict)] if isinstance(values, list) else []
        summary[str(kind)] = {
            "count": len(points),
            "hookable_count": sum(1 for item in points if bool(item.get("hookable"))),
        }
    return summary


def _first_captured_breakpoint_material(hook_results: dict[str, str]) -> str:
    for key in (
        "utf16le_payload",
        "base64_input",
        "base64_output",
        "rc4_key",
        "rc4_input",
        "rc4_output",
        "compare_buffer",
    ):
        if hook_results.get(key) in {"available", "inferred"}:
            return key
    return ""


def _breakpoint_next_bottleneck(
    *,
    classification: str,
    hook_results: dict[str, str],
    candidate_errors: Sequence[str],
    hookable_static_points: Sequence[dict[str, object]],
) -> str:
    if classification == "breakpoint_probe_complete":
        return "actual transform divergence"
    if classification == "base64_rc4_static_points_unavailable":
        return "static point discovery"
    if classification == "base64_rc4_hook_failed" or candidate_errors:
        return "runtime GUI triggering"
    if hook_results.get("compare_buffer") in {"available", "inferred"}:
        return "compare-only capture"
    if hookable_static_points:
        return "hook placement"
    return "static point discovery"


def _breakpoint_material_status(hook_results: dict[str, str], *keys: str) -> str:
    values = [hook_results.get(key, "unavailable") for key in keys]
    if "available" in values:
        return "confirmed"
    if "inferred" in values:
        return "inferred"
    return "unknown"


def _breakpoint_exact2_failure_trace(
    expected: dict[str, object],
    hook_results: dict[str, str],
) -> dict[str, object]:
    trace = _exact2_failure_trace_from_expected(expected)
    trace.update(
        {
            "prga_positions": [4, 5] if hook_results.get("rc4_output") in {"available", "inferred"} else [],
            "candidate_byte_dependencies": [],
            "bounded_constraint": (
                "runtime RC4/Base64 construction evidence captured; derive byte constraints in the next bounded diagnostic"
                if any(hook_results.get(key) in {"available", "inferred"} for key in ("base64_input", "base64_output", "rc4_key", "rc4_input", "rc4_output"))
                else "RC4/Base64 construction point unavailable; key/input dependency model remains unknown"
            ),
        }
    )
    return trace


def run_base64_rc4_breakpoint_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log,
    static_points: dict[str, list[dict[str, object]]] | None = None,
) -> dict[str, object]:
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / BASE64_RC4_BREAKPOINT_PROBE_FILE_NAME
    script_path = _base64_rc4_breakpoint_probe_script_path()
    static_points = static_points if static_points is not None else _base64_rc4_static_points(target)
    entries = _breakpoint_probe_entries(transform_model)
    payload: dict[str, object] = {
        "artifact_kind": "base64_rc4_breakpoint_probe",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(BASE64_RC4_BREAKPOINT_PROBE_CANDIDATES),
        "validation_candidates": entries,
        "static_points": static_points,
        "promotable_validations": [],
    }
    _write_json(result_path, payload)
    if not script_path.exists():
        raise RuntimeError(f"Base64/RC4 breakpoint probe script missing: {script_path}")

    candidate_results: list[dict[str, object]] = []
    points_path = artifacts_dir / "static_points.json"
    _write_json(points_path, {"static_points": static_points})
    for idx, entry in enumerate(entries, 1):
        candidate_hex = str(entry["candidate_hex"])
        candidate_dir = artifacts_dir / f"candidate_{idx}"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        compare_out = candidate_dir / "base64_rc4_breakpoint_probe_compare.json"
        compare_log = candidate_dir / "base64_rc4_breakpoint_probe_compare.log"
        command = [
            sys.executable,
            str(script_path),
            "--target",
            str(target),
            "--out",
            str(compare_out),
            "--points",
            str(points_path),
            "--probe-hex",
            candidate_hex,
            "--per-probe-timeout",
            str(per_probe_timeout),
        ]
        if log:
            log(f"Base64RC4BreakpointProbe scripted breakpoints {idx}: {candidate_hex}")
        proc = subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        compare_log.write_text(
            f"[stdout]\n{proc.stdout or ''}\n\n[stderr]\n{proc.stderr or ''}",
            encoding="utf-8",
        )
        compare_payload = _read_json_object(compare_out) if compare_out.exists() else {}
        hook_events = [
            dict(item)
            for item in list(compare_payload.get("hook_events", []))
            if isinstance(item, dict)
        ]
        hook_results = (
            dict(compare_payload.get("hook_results", {}))
            if isinstance(compare_payload.get("hook_results"), dict)
            else {}
        )
        construction_hit = any(
            str(item.get("point_kind", "")) in {"utf16le", "base64", "rc4_ksa", "rc4_prga", "encrypted_const"}
            for item in hook_events
        )
        candidate_results.append(
            {
                "label": entry.get("label", f"base64_rc4_breakpoint_probe_{idx}"),
                "candidate_hex": candidate_hex,
                "probe_role": entry.get("probe_role", ""),
                "runtime_backed": bool(hook_events),
                "construction_hit": construction_hit,
                "hook_results": hook_results,
                "hook_events": hook_events[:20],
                "result_path": str(compare_out),
                "log_path": str(compare_log),
                "success": bool(compare_payload.get("success")),
                "error": str(compare_payload.get("error", "")),
            }
        )

    runtime_backed_count = sum(1 for item in candidate_results if bool(item.get("runtime_backed")))
    construction_hit_count = sum(1 for item in candidate_results if bool(item.get("construction_hit")))
    hook_results = _aggregate_breakpoint_hook_results(candidate_results)
    material_statuses = [
        hook_results.get(key, "unavailable")
        for key in ("utf16le_payload", "base64_input", "base64_output", "rc4_key", "rc4_input", "rc4_output")
    ]
    hookable_static_points = [
        point
        for values in static_points.values()
        for point in values
        if isinstance(point, dict) and bool(point.get("hookable"))
    ]
    candidate_errors = [
        str(item.get("error", ""))
        for item in candidate_results
        if str(item.get("error", "")).strip()
    ]
    classification = (
        "breakpoint_probe_complete"
        if any(value in {"available", "inferred"} for value in material_statuses)
        else "base64_rc4_static_points_unavailable"
        if not hookable_static_points
        else "base64_rc4_hook_failed"
        if candidate_errors and not runtime_backed_count
        else "base64_rc4_compare_only"
        if hook_results.get("compare_buffer") in {"available", "inferred"}
        else "breakpoint_probe_partial"
    )
    hook_event_count = sum(
        len(list(item.get("hook_events", [])))
        for item in candidate_results
        if isinstance(item.get("hook_events"), list)
    )
    first_captured_material_kind = _first_captured_breakpoint_material(hook_results)
    next_bottleneck = _breakpoint_next_bottleneck(
        classification=classification,
        hook_results=hook_results,
        candidate_errors=candidate_errors,
        hookable_static_points=hookable_static_points,
    )
    first_expected = dict(entries[0].get("expected_materials", {})) if entries else {}
    findings = [
        "scripted breakpoint/access probe captured Base64 or RC4 construction evidence"
        if construction_hit_count
        else "scripted breakpoint/access probe did not capture Base64 or RC4 construction evidence",
        "candidate generation, ranking, final selection, and search budget were unchanged",
    ]
    payload.update(
        {
            "classification": classification,
            "runtime_backed_count": runtime_backed_count,
            "construction_hit_count": construction_hit_count,
            "hook_event_count": hook_event_count,
            "hook_results": hook_results,
            "static_point_summary": _breakpoint_static_point_summary(static_points),
            "first_captured_material_kind": first_captured_material_kind,
            "next_bottleneck": next_bottleneck,
            "candidate_results": candidate_results,
            "rc4_key": {
                "status": _breakpoint_material_status(hook_results, "rc4_key"),
                "key_ptr": "",
                "key_len": None,
                "key_preview_hex": "",
                "source_hypothesis": "runtime_constructed" if hook_results.get("rc4_key") in {"available", "inferred"} else "unknown",
            },
            "rc4_input": {
                "status": _breakpoint_material_status(hook_results, "rc4_input"),
                "input_ptr": "",
                "input_len": None,
                "input_preview_hex": "",
                "input_preview_ascii": "",
                "matches_offline_base64": None,
            },
            "base64_material": {
                "status": _breakpoint_material_status(hook_results, "base64_input", "base64_output"),
                "input_preview_hex": "",
                "output_preview_ascii": "",
                "alphabet": "standard" if any(point.get("name") == "standard_base64_alphabet" for point in static_points.get("base64", [])) else "unknown",
                "padding_behavior": "unknown",
            },
            "exact2_failure_trace": _breakpoint_exact2_failure_trace(first_expected, hook_results),
            "findings": findings,
            "next_bounded_action": (
                "derive bounded exact3 constraints from captured Base64/RC4 construction evidence"
                if classification == "breakpoint_probe_complete"
                else "locate hookable Base64/RC4 construction points with IDA/x64dbg before repeating scripted breakpoint capture"
                if classification == "base64_rc4_static_points_unavailable"
                else "repair Frida/UI triggering before repeating the bounded breakpoint capture"
                if classification == "base64_rc4_hook_failed"
                else "audit hook placement: compare fired, but Base64/RC4 construction hooks did not"
                if classification == "base64_rc4_compare_only"
                else "use manual IDA/x64dbg breakpoints with the recorded static offsets"
                if hookable_static_points
                else "use manual IDA/x64dbg to locate Base64/RC4 construction points; current static scan found no hookable offsets"
            ),
            "promotable_validations": [],
        }
    )
    _write_json(result_path, payload)
    if log:
        log(f"Base64/RC4 breakpoint probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "validations": candidate_results,
        "promotable_validations": [],
    }


def _hex_to_bytes(value: object) -> bytes:
    text = str(value or "").strip().lower()
    if len(text) % 2:
        return b""
    try:
        return bytes.fromhex(text)
    except ValueError:
        return b""


def _parse_int_hex(value: object) -> int | None:
    text = str(value or "").strip().lower()
    if not text:
        return None
    try:
        return int(text, 16) if text.startswith("0x") else int(text)
    except ValueError:
        return None


def _material_hex(expected: dict[str, object], name: str) -> str:
    materials = expected.get("materials", [])
    if not isinstance(materials, list):
        return ""
    for item in materials:
        if isinstance(item, dict) and str(item.get("name", "")) == name:
            return str(item.get("hex", "")).strip().lower()
    return ""


def _stack_material_match(
    *,
    stack_preview_hex: object,
    material_hex: str,
    esp: object,
    ebp: object,
) -> dict[str, object]:
    stack = _hex_to_bytes(stack_preview_hex)
    material = _hex_to_bytes(material_hex)
    if not stack or not material:
        return {
            "visible": False,
            "stack_offset": None,
            "matched_bytes": 0,
            "expected_bytes": len(material),
            "match_ratio": 0.0,
        }
    offset = stack.find(material)
    if offset < 0:
        best_offset = -1
        best_len = 0
        for idx in range(len(stack)):
            length = 0
            while idx + length < len(stack) and length < len(material) and stack[idx + length] == material[length]:
                length += 1
            if length > best_len:
                best_offset = idx
                best_len = length
        offset = best_offset
        matched = best_len
    else:
        matched = len(material)
    visible = offset >= 0 and matched >= min(16, len(material))
    esp_value = _parse_int_hex(esp)
    ebp_value = _parse_int_hex(ebp)
    absolute = esp_value + offset if visible and esp_value is not None else None
    ebp_relative = absolute - ebp_value if absolute is not None and ebp_value is not None else None
    return {
        "visible": visible,
        "stack_offset": offset if visible else None,
        "esp_relative": f"+0x{offset:x}" if visible else "",
        "absolute_address": f"0x{absolute:x}" if absolute is not None else "",
        "ebp_relative": f"-0x{abs(ebp_relative):x}" if isinstance(ebp_relative, int) and ebp_relative < 0 else (
            f"+0x{ebp_relative:x}" if isinstance(ebp_relative, int) else ""
        ),
        "matched_bytes": matched if visible else 0,
        "expected_bytes": len(material),
        "match_ratio": round((matched / len(material)) if material else 0.0, 4),
    }


def _compare_stack_static_audit(target: Path) -> dict[str, object]:
    expected: dict[str, object] = {
        "wide_flag": {
            "expected_va": "0x551c4c",
            "expected_rva": "0x151c4c",
            "hits": [],
        },
        "compare_site": {
            "expected_call_rva": "0x258c",
            "helper_rva": "",
            "helper_classification": "unknown",
        },
        "backward_slice": [],
        "next_hook_points": [],
        "classification": "static_anchor_ambiguous",
        "errors": [],
    }
    try:
        data = target.read_bytes()
    except OSError as exc:
        expected["errors"] = [f"target_read_failed:{exc}"]
        return expected

    sections = _pe_sections_for_rva_mapping(data)
    try:
        pe_offset = int.from_bytes(data[0x3C:0x40], "little")
        optional_header = pe_offset + 24
        magic = int.from_bytes(data[optional_header:optional_header + 2], "little")
        image_base_offset = optional_header + (28 if magic == 0x10B else 24)
        image_base = int.from_bytes(data[image_base_offset:image_base_offset + (4 if magic == 0x10B else 8)], "little")
    except Exception as exc:
        expected["errors"] = [f"pe_parse_failed:{exc}"]
        return expected

    wide_hits: list[dict[str, object]] = []
    start = 0
    while True:
        found = data.find(TARGET_PREFIX, start)
        if found < 0:
            break
        rva = _file_offset_to_rva(found, sections)
        wide_hits.append(
            {
                "file_offset": f"0x{found:x}",
                "rva": f"0x{rva:x}" if rva is not None else "",
                "va": f"0x{image_base + rva:x}" if rva is not None else "",
            }
        )
        start = found + 1
    expected["wide_flag"] = {
        "expected_va": "0x551c4c",
        "expected_rva": "0x151c4c",
        "hits": wide_hits,
    }

    xrefs: list[dict[str, object]] = []
    if wide_hits:
        first_rva_text = str(wide_hits[0].get("rva", ""))
        first_rva = int(first_rva_text, 16) if first_rva_text.startswith("0x") else None
        if first_rva is not None:
            needle = int(image_base + first_rva).to_bytes(4, "little")
            start = 0
            while True:
                found = data.find(needle, start)
                if found < 0:
                    break
                rva = _file_offset_to_rva(found, sections)
                push_rva = rva - 1 if rva is not None and found > 0 and data[found - 1] == 0x68 else None
                xrefs.append(
                    {
                        "file_offset": f"0x{found:x}",
                        "rva": f"0x{rva:x}" if rva is not None else "",
                        "instruction_rva": f"0x{push_rva:x}" if push_rva is not None else "",
                    }
                )
                start = found + 1

    compare_call_rva: int | None = None
    helper_rva: int | None = None
    if len(xrefs) == 1:
        xref_rva = int(str(xrefs[0].get("rva", "0")), 16)
        compare_call_rva = xref_rva + 5
        call_offset = None
        for section in sections:
            virtual_address = int(section.get("virtual_address", 0))
            raw_pointer = int(section.get("raw_pointer", 0))
            span = max(int(section.get("raw_size", 0)), int(section.get("virtual_size", 0)), 1)
            if virtual_address <= compare_call_rva < virtual_address + span:
                call_offset = raw_pointer + (compare_call_rva - virtual_address)
                break
        if call_offset is not None and call_offset + 5 <= len(data) and data[call_offset] == 0xE8:
            rel = int.from_bytes(data[call_offset + 1:call_offset + 5], "little", signed=True)
            helper_rva = compare_call_rva + 5 + rel
    helper_classification = "unknown"
    if helper_rva is not None:
        helper_offset = None
        for section in sections:
            virtual_address = int(section.get("virtual_address", 0))
            raw_pointer = int(section.get("raw_pointer", 0))
            span = max(int(section.get("raw_size", 0)), int(section.get("virtual_size", 0)), 1)
            if virtual_address <= helper_rva < virtual_address + span:
                helper_offset = raw_pointer + (helper_rva - virtual_address)
                break
        helper_bytes = data[helper_offset:helper_offset + 0x90] if helper_offset is not None else b""
        if (
            b"\x83\xf8\x41" in helper_bytes
            and b"\x83\xf8\x5a" in helper_bytes
            and b"\x83\xc0\x20" in helper_bytes
            and b"\x66\x3b\xd0" in helper_bytes
        ):
            helper_classification = "case_insensitive_wchar_compare"

    backward_slice = [
        {
            "rva": "0x253a",
            "operation": "store candidate output pointer into [ebp-0x1170]",
            "instruction": "mov dword ptr [ebp - 0x1170], eax",
        },
        {
            "rva": "0x2554",
            "operation": "handoff/copy helper before compare buffer reload",
            "instruction": "call 0x401b50",
        },
        {
            "rva": "0x2559",
            "operation": "reload compare lhs pointer from [ebp-0x1170]",
            "instruction": "mov esi, dword ptr [ebp - 0x1170]",
        },
        {
            "rva": "0x2584",
            "operation": "set wide compare count",
            "instruction": "push 5",
        },
        {
            "rva": "0x2586",
            "operation": "push wide flag target",
            "instruction": "push 0x551c4c",
        },
        {
            "rva": "0x258b",
            "operation": "push compare lhs pointer",
            "instruction": "push esi",
        },
        {
            "rva": "0x258c",
            "operation": "case-insensitive wide compare call",
            "instruction": "call 0x5028ac",
        },
    ]
    next_hook_points = [
        {
            "name": "post_handoff_lhs_reload",
            "module_offset": 0x2559,
            "address": "module+0x2559",
            "reason": "first instruction after call 0x401b50 reloads [ebp-0x1170] into esi",
        },
        {
            "name": "handoff_helper_enter",
            "module_offset": 0x1B50,
            "address": "module+0x1b50",
            "reason": "captures arguments to the helper that runs before the compare buffer is reloaded",
        },
        {
            "name": "handoff_helper_return",
            "module_offset": 0x2559,
            "address": "module+0x2559",
            "reason": "captures [ebp-0x1170], esi, and stack payload immediately after helper return",
        },
    ]
    expected.update(
        {
            "wide_flag_xrefs": xrefs,
            "compare_site": {
                "expected_call_rva": "0x258c",
                "actual_call_rva": f"0x{compare_call_rva:x}" if compare_call_rva is not None else "",
                "helper_rva": f"0x{helper_rva:x}" if helper_rva is not None else "",
                "helper_va": f"0x{image_base + helper_rva:x}" if helper_rva is not None else "",
                "helper_classification": helper_classification,
            },
            "backward_slice": backward_slice,
            "next_hook_points": next_hook_points,
            "classification": (
                "static_anchor_confirmed"
                if len(wide_hits) == 1
                and len(xrefs) == 1
                and compare_call_rva == 0x258C
                and helper_rva == 0x1028AC
                and helper_classification == "case_insensitive_wchar_compare"
                else "static_anchor_ambiguous"
            ),
        }
    )
    return expected


def _compare_stack_entries_from_breakpoint_payload(
    breakpoint_payload: dict[str, object],
) -> list[dict[str, object]]:
    validation_by_candidate: dict[str, dict[str, object]] = {}
    for item in breakpoint_payload.get("validation_candidates", []):
        if isinstance(item, dict):
            candidate_hex = str(item.get("candidate_hex", "")).strip().lower()
            if candidate_hex:
                validation_by_candidate[candidate_hex] = item

    entries: list[dict[str, object]] = []
    for idx, item in enumerate(breakpoint_payload.get("candidate_results", []), 1):
        if not isinstance(item, dict):
            continue
        candidate_hex = str(item.get("candidate_hex", "")).strip().lower()
        validation = validation_by_candidate.get(candidate_hex, {})
        expected = validation.get("expected_materials", {})
        expected = expected if isinstance(expected, dict) else {}
        utf16_hex = _material_hex(expected, "utf16le_payload")
        compare_events = [
            event
            for event in item.get("hook_events", [])
            if isinstance(event, dict) and str(event.get("point_kind", "")) == "compare"
        ]
        event_results: list[dict[str, object]] = []
        for event in compare_events:
            registers = event.get("registers", {})
            registers = registers if isinstance(registers, dict) else {}
            match = _stack_material_match(
                stack_preview_hex=event.get("stack_preview_hex", ""),
                material_hex=utf16_hex,
                esp=registers.get("esp", ""),
                ebp=registers.get("ebp", ""),
            )
            event_results.append(
                {
                    **match,
                    "point_name": event.get("point_name", ""),
                    "address": event.get("address", ""),
                    "module_offset": event.get("module_offset", ""),
                    "lhs_ptr": event.get("lhs_ptr", ""),
                    "rhs_ptr": event.get("rhs_ptr", ""),
                    "compare_count": event.get("compare_count"),
                    "lhs_preview_hex": event.get("lhs_preview_hex", ""),
                    "rhs_preview_hex": event.get("rhs_preview_hex", ""),
                    "stack_preview_bytes": len(_hex_to_bytes(event.get("stack_preview_hex", ""))),
                }
            )
        best = max(event_results, key=lambda result: int(result.get("matched_bytes", 0) or 0), default={})
        entries.append(
            {
                "label": item.get("label", f"compare_stack_pivot_probe_{idx}"),
                "candidate_hex": candidate_hex,
                "probe_role": item.get("probe_role", ""),
                "runtime_backed": bool(item.get("runtime_backed")),
                "compare_event_count": len(compare_events),
                "utf16le_payload_status": "available_from_compare_stack" if best.get("visible") else "unavailable",
                "utf16le_payload": {
                    "expected_length_bytes": len(_hex_to_bytes(utf16_hex)),
                    "best_match": best,
                    "events": event_results[:5],
                },
            }
        )
    return entries


def run_compare_stack_pivot_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    breakpoint_probe_payload: dict[str, object] | None = None,
    log=None,
) -> dict[str, object]:
    _ = transform_model
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / COMPARE_STACK_PIVOT_PROBE_FILE_NAME
    if breakpoint_probe_payload is None:
        breakpoint_probe_payload, source_path = _indexed_artifact_payload("base64_rc4_breakpoint_probe")
    else:
        source_path = ""
    breakpoint_probe_payload = breakpoint_probe_payload or {}
    entries = _compare_stack_entries_from_breakpoint_payload(breakpoint_probe_payload)
    visible_count = sum(
        1 for item in entries if str(item.get("utf16le_payload_status", "")) == "available_from_compare_stack"
    )
    runtime_backed_count = sum(1 for item in entries if bool(item.get("runtime_backed")))
    static_audit = _compare_stack_static_audit(target)
    classification = (
        "compare_stack_pivot_complete"
        if visible_count == len(entries) and entries and static_audit.get("classification") == "static_anchor_confirmed"
        else "compare_stack_pivot_partial"
        if visible_count or static_audit.get("classification") == "static_anchor_confirmed"
        else "compare_stack_pivot_unavailable"
    )
    payload: dict[str, object] = {
        "artifact_kind": "compare_stack_pivot_probe",
        "profile": "samplereverse",
        "attempted": True,
        "source_artifact": source_path,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(COMPARE_STACK_PIVOT_PROBE_CANDIDATES),
        "runtime_backed_count": runtime_backed_count,
        "utf16le_payload_available_count": visible_count,
        "classification": classification,
        "static_audit": static_audit,
        "stack_results": entries,
        "hook_results": {
            "utf16le_payload": "available_from_compare_stack" if visible_count else "unavailable",
            "base64_input": "unavailable",
            "base64_output": "unavailable",
            "rc4_key": "unavailable",
            "rc4_input": "unavailable",
            "rc4_output": "unavailable",
            "compare_buffer": "available" if runtime_backed_count else "unavailable",
        },
        "next_hook_points": static_audit.get("next_hook_points", []),
        "promotable_validations": [],
        "findings": [
            "compare-frame stack contains the UTF-16LE expanded payload"
            if visible_count
            else "compare-frame stack did not expose the UTF-16LE expanded payload",
            "candidate generation, ranking, final selection, and search budget were unchanged",
        ],
        "next_bounded_action": (
            "hook module+0x1b50 enter/return and module+0x2559 to capture the handoff into [ebp-0x1170]"
            if visible_count
            else "manual IDA/x64dbg breakpoints are required; compare stack pivot did not expose payload"
        ),
    }
    _write_json(result_path, payload)
    if log:
        log(f"Compare stack pivot probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "validations": entries,
        "promotable_validations": [],
    }


def _compare_handoff_hook_points(static_audit: dict[str, object]) -> list[dict[str, object]]:
    return [
        {
            "name": "pre_lhs_slot_store",
            "module_offset": 0x253A,
            "address": "module+0x253a",
            "reason": "captures eax before it is stored into [ebp-0x1170]",
        },
        {
            "name": "pre_handoff_call",
            "module_offset": 0x2554,
            "address": "module+0x2554",
            "reason": "captures [ebp-0x1170] immediately before call 0x401b50",
        },
        {
            "name": "handoff_helper_enter",
            "module_offset": 0x1B50,
            "address": "module+0x1b50",
            "reason": "captures arguments and registers at helper entry",
        },
        {
            "name": "post_handoff_lhs_reload",
            "module_offset": 0x2559,
            "address": "module+0x2559",
            "reason": "captures [ebp-0x1170] and esi after helper return, before reload",
        },
        {
            "name": "pre_compare_push_esi",
            "module_offset": 0x258B,
            "address": "module+0x258b",
            "reason": "captures esi immediately before it is pushed as compare lhs",
        },
        {
            "name": "wide_flag_prefix_compare",
            "module_offset": 0x258C,
            "address": "module+0x258c",
            "reason": "cross-checks compare lhs/rhs/count at the compare call",
        },
    ]


def _compare_handoff_audit(static_audit: dict[str, object]) -> dict[str, object]:
    compare_site = static_audit.get("compare_site", {})
    compare_site = compare_site if isinstance(compare_site, dict) else {}
    return {
        "compare_call_rva": str(compare_site.get("actual_call_rva") or compare_site.get("expected_call_rva") or ""),
        "handoff_helper_rva": "0x1b50",
        "post_handoff_reload_rva": "0x2559",
        "lhs_slot": "[ebp-0x1170]",
        "static_anchor_valid": static_audit.get("classification") == "static_anchor_confirmed",
        "reason": list(static_audit.get("errors", [])) if isinstance(static_audit.get("errors"), list) else [],
    }


def _preview_utf16le(value: object) -> str:
    raw = _hex_to_bytes(value)
    if not raw:
        return ""
    try:
        return raw.decode("utf-16le", errors="ignore").split("\x00", 1)[0]
    except UnicodeDecodeError:
        return ""


def _handoff_metric_from_preview(value: object) -> dict[str, object]:
    raw = _hex_to_bytes(value)
    if not raw:
        return {"runtime_ci_exact_wchars": 0, "runtime_ci_distance5": 0}
    score = score_compare_prefix(raw[: len(TARGET_PREFIX)])
    return {
        "runtime_ci_exact_wchars": score.get("ci_exact_wchars", 0),
        "runtime_ci_distance5": score.get("ci_distance5", 0),
    }


def _normalize_handoff_observation(item: dict[str, object], candidate_hex: str) -> dict[str, object]:
    preview_hex = (
        str(item.get("lhs_buffer_preview_hex") or "")
        or str(item.get("lhs_slot_preview_hex") or "")
        or str(item.get("esi_preview_hex") or "")
        or str(item.get("eax_preview_hex") or "")
    )
    metrics = _handoff_metric_from_preview(preview_hex)
    return {
        "hook_name": str(item.get("hook_name", "")),
        "address": str(item.get("address", "")),
        "module_offset": str(item.get("module_offset", "")),
        "registers": dict(item.get("registers", {})) if isinstance(item.get("registers"), dict) else {},
        "stack_preview_hex": str(item.get("stack_preview_hex", "")),
        "lhs_slot_ptr": str(item.get("lhs_slot_ptr", "")),
        "lhs_slot_preview_hex": str(item.get("lhs_slot_preview_hex", "")),
        "eax_ptr": str(item.get("eax_ptr", "")),
        "eax_preview_hex": str(item.get("eax_preview_hex", "")),
        "esi_ptr": str(item.get("esi_ptr", "")),
        "esi_preview_hex": str(item.get("esi_preview_hex", "")),
        "lhs_ptr": str(item.get("lhs_ptr", "")),
        "rhs_ptr": str(item.get("rhs_ptr", "")),
        "compare_count": item.get("compare_count"),
        "lhs_buffer_preview_hex": preview_hex,
        "lhs_buffer_preview_utf16le": str(item.get("lhs_buffer_preview_utf16le") or _preview_utf16le(preview_hex)),
        "candidate_hex": candidate_hex,
        "candidate_prefix": candidate_hex[:16],
        "runtime_ci_exact_wchars": metrics["runtime_ci_exact_wchars"],
        "runtime_ci_distance5": metrics["runtime_ci_distance5"],
    }


def _aggregate_handoff_hook_results(candidate_results: list[dict[str, object]]) -> dict[str, str]:
    names: set[str] = set()
    lhs_slot_available = False
    compare_lhs_available = False
    for result in candidate_results:
        for item in result.get("hook_observations", []):
            if not isinstance(item, dict):
                continue
            names.add(str(item.get("hook_name", "")))
            lhs_slot_available = lhs_slot_available or bool(str(item.get("lhs_slot_ptr", "")))
            compare_lhs_available = compare_lhs_available or bool(str(item.get("lhs_buffer_preview_hex", "")))
    return {
        "handoff_helper_enter": "available" if "handoff_helper_enter" in names else "unavailable",
        "handoff_helper_return": "available" if "handoff_helper_return" in names else "unavailable",
        "post_handoff_lhs_reload": "available" if "post_handoff_lhs_reload" in names else "unavailable",
        "compare_lhs_buffer": "available" if compare_lhs_available else "unavailable",
        "lhs_slot": "available" if lhs_slot_available else "unavailable",
    }


def run_compare_handoff_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log=None,
) -> dict[str, object]:
    _ = transform_model
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / COMPARE_HANDOFF_PROBE_FILE_NAME
    script_path = _compare_handoff_probe_script_path()
    static_audit = _compare_stack_static_audit(target)
    hook_points = _compare_handoff_hook_points(static_audit)
    entries = list(COMPARE_HANDOFF_PROBE_CANDIDATES)
    payload: dict[str, object] = {
        "artifact_kind": "compare_handoff_probe",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(COMPARE_HANDOFF_PROBE_CANDIDATES),
        "compare_stack_pivot_audit": _compare_handoff_audit(static_audit),
        "hook_points": hook_points,
        "promotable_validations": [],
    }
    _write_json(result_path, payload)
    if not script_path.exists():
        raise RuntimeError(f"Compare handoff probe script missing: {script_path}")

    points_path = artifacts_dir / "hook_points.json"
    _write_json(points_path, {"hook_points": hook_points})
    candidate_results: list[dict[str, object]] = []
    for idx, candidate_hex in enumerate(entries, 1):
        candidate_dir = artifacts_dir / f"candidate_{idx}"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        compare_out = candidate_dir / "compare_handoff_probe.json"
        compare_log = candidate_dir / "compare_handoff_probe.log"
        command = [
            sys.executable,
            str(script_path),
            "--target",
            str(target),
            "--out",
            str(compare_out),
            "--points",
            str(points_path),
            "--probe-hex",
            candidate_hex,
            "--per-probe-timeout",
            str(per_probe_timeout),
        ]
        if log:
            log(f"CompareHandoffProbe scripted hooks {idx}: {candidate_hex}")
        proc = subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        compare_log.write_text(
            f"[stdout]\n{proc.stdout or ''}\n\n[stderr]\n{proc.stderr or ''}",
            encoding="utf-8",
        )
        compare_payload = _read_json_object(compare_out) if compare_out.exists() else {}
        observations = [
            _normalize_handoff_observation(dict(item), candidate_hex)
            for item in compare_payload.get("hook_observations", [])
            if isinstance(item, dict)
        ]
        candidate_results.append(
            {
                "label": f"compare_handoff_probe_{idx}",
                "candidate_hex": candidate_hex,
                "candidate_prefix": candidate_hex[:16],
                "runtime_backed": bool(observations),
                "hook_results": dict(compare_payload.get("hook_results", {}))
                if isinstance(compare_payload.get("hook_results"), dict)
                else {},
                "hook_observations": observations[:30],
                "result_path": str(compare_out),
                "log_path": str(compare_log),
                "success": bool(compare_payload.get("success")),
                "error": str(compare_payload.get("error", "")),
            }
        )

    runtime_backed_count = sum(1 for item in candidate_results if bool(item.get("runtime_backed")))
    hook_results = _aggregate_handoff_hook_results(candidate_results)
    complete = all(
        hook_results.get(key) == "available"
        for key in (
            "handoff_helper_enter",
            "handoff_helper_return",
            "post_handoff_lhs_reload",
            "compare_lhs_buffer",
            "lhs_slot",
        )
    )
    classification = (
        "handoff_capture_complete"
        if complete
        else "handoff_capture_partial"
        if runtime_backed_count
        else "handoff_capture_failed"
    )
    payload.update(
        {
            "classification": classification,
            "runtime_backed_count": runtime_backed_count,
            "hook_results": hook_results,
            "candidate_results": candidate_results,
            "handoff_observations": [
                observation
                for result in candidate_results
                for observation in result.get("hook_observations", [])
                if isinstance(observation, dict)
            ][:60],
            "findings": [
                "compare lhs handoff hooks captured runtime observations"
                if runtime_backed_count
                else "compare lhs handoff hooks did not capture runtime observations",
                "candidate generation, ranking, final selection, and search budget were unchanged",
            ],
            "next_bounded_action": (
                "derive buffer-level byte constraints from captured compare lhs handoff buffers"
                if classification == "handoff_capture_complete"
                else "perform a narrower backward slice from 0x401b50 helper arguments"
                if classification == "handoff_capture_partial"
                else "revalidate static hook addresses for module+0x1b50 and module+0x2559 before any search expansion"
            ),
            "promotable_validations": [],
        }
    )
    _write_json(result_path, payload)
    if log:
        log(f"Compare handoff probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "validations": candidate_results,
        "promotable_validations": [],
    }


def _compare_handoff_slice_hook_points(static_audit: dict[str, object]) -> list[dict[str, object]]:
    _ = static_audit
    return [
        {
            "name": "pre_lhs_slot_store",
            "module_offset": 0x253A,
            "address": "module+0x253a",
            "reason": "captures eax immediately before [ebp-0x1170] is written",
        },
        {
            "name": "pre_handoff_call",
            "module_offset": 0x2554,
            "address": "module+0x2554",
            "reason": "captures helper call-site registers, stack words, and [ebp-0x1170]",
        },
        {
            "name": "handoff_helper_enter",
            "module_offset": 0x1B50,
            "address": "module+0x1b50",
            "reason": "captures helper entry arguments and caller return address",
        },
        {
            "name": "post_handoff_lhs_reload",
            "module_offset": 0x2559,
            "address": "module+0x2559",
            "reason": "revalidates the prior post-helper reload anchor",
        },
        {
            "name": "post_handoff_after_reload",
            "module_offset": 0x255C,
            "address": "module+0x255c",
            "reason": "instruction-confirmed fallback after the reload window",
        },
        {
            "name": "pre_compare_push_esi",
            "module_offset": 0x258B,
            "address": "module+0x258b",
            "reason": "captures esi immediately before compare lhs is pushed",
        },
        {
            "name": "wide_flag_prefix_compare",
            "module_offset": 0x258C,
            "address": "module+0x258c",
            "reason": "cross-checks compare lhs/rhs/count at the compare call",
        },
    ]


def _pointer_text_equal(left: object, right: object) -> bool:
    left_text = str(left or "").strip().lower()
    right_text = str(right or "").strip().lower()
    return bool(left_text and right_text and left_text not in {"0x0", "0"} and left_text == right_text)


def _preview_text_equal(left: object, right: object) -> bool:
    left_text = str(left or "").strip().lower()
    right_text = str(right or "").strip().lower()
    if not left_text or not right_text:
        return False
    return left_text[:32] == right_text[:32]


def _first_observation(observations: list[dict[str, object]], hook_name: str) -> dict[str, object]:
    return next((item for item in observations if str(item.get("hook_name", "")) == hook_name), {})


def _helper_arg_map_from_observations(observations: list[dict[str, object]]) -> dict[str, object]:
    pre_store = _first_observation(observations, "pre_lhs_slot_store")
    pre_call = _first_observation(observations, "pre_handoff_call")
    helper_enter = _first_observation(observations, "handoff_helper_enter")
    helper_return = _first_observation(observations, "handoff_helper_return")
    post_reload = _first_observation(observations, "post_handoff_lhs_reload")
    post_after_reload = _first_observation(observations, "post_handoff_after_reload")
    pre_compare = _first_observation(observations, "pre_compare_push_esi")
    compare = _first_observation(observations, "wide_flag_prefix_compare")
    compare_lhs_ptr = compare.get("lhs_ptr") or pre_compare.get("esi_ptr")
    compare_lhs_preview = compare.get("lhs_buffer_preview_hex") or pre_compare.get("esi_preview_hex")
    return {
        "pre_store": {
            "source": "eax before mov [ebp-0x1170], eax",
            "eax_ptr": pre_store.get("eax_ptr", ""),
            "eax_preview_hex": pre_store.get("eax_preview_hex", ""),
        },
        "pre_call": {
            "source": "call-site immediately before call 0x401b50",
            "eax_ptr": pre_call.get("eax_ptr", ""),
            "ecx": dict(pre_call.get("registers", {})).get("ecx", "") if isinstance(pre_call.get("registers"), dict) else "",
            "edx": dict(pre_call.get("registers", {})).get("edx", "") if isinstance(pre_call.get("registers"), dict) else "",
            "esi_ptr": pre_call.get("esi_ptr", ""),
            "lhs_slot_ptr": pre_call.get("lhs_slot_ptr", ""),
            "stack_words": pre_call.get("stack_words", []),
        },
        "helper_enter": {
            "source": "0x401b50 entry",
            "return_address": helper_enter.get("return_address", ""),
            "return_address_module_offset": helper_enter.get("return_address_module_offset", ""),
            "eax_ptr": helper_enter.get("eax_ptr", ""),
            "ecx": dict(helper_enter.get("registers", {})).get("ecx", "") if isinstance(helper_enter.get("registers"), dict) else "",
            "edx": dict(helper_enter.get("registers", {})).get("edx", "") if isinstance(helper_enter.get("registers"), dict) else "",
            "esi_ptr": helper_enter.get("esi_ptr", ""),
            "lhs_slot_ptr": helper_enter.get("lhs_slot_ptr", ""),
            "stack_words": helper_enter.get("stack_words", []),
        },
        "helper_return": {
            "source": "0x401b50 onLeave",
            "eax_ptr": helper_return.get("eax_ptr", ""),
            "eax_preview_hex": helper_return.get("eax_preview_hex", ""),
            "esi_ptr": helper_return.get("esi_ptr", ""),
            "lhs_slot_ptr": helper_return.get("lhs_slot_ptr", ""),
            "lhs_slot_preview_hex": helper_return.get("lhs_slot_preview_hex", ""),
        },
        "post_helper": {
            "prior_reload_anchor_observed": bool(post_reload),
            "fallback_after_reload_observed": bool(post_after_reload),
            "post_reload_lhs_slot_ptr": post_reload.get("lhs_slot_ptr", ""),
            "post_after_reload_esi_ptr": post_after_reload.get("esi_ptr", ""),
        },
        "compare_lhs": {
            "source": "wide_flag_prefix_compare lhs or pre_compare esi",
            "lhs_ptr": compare_lhs_ptr or "",
            "lhs_preview_hex": compare_lhs_preview or "",
            "compare_count": compare.get("compare_count"),
        },
        "relations": {
            "pre_call_slot_matches_helper_enter_slot": _pointer_text_equal(
                pre_call.get("lhs_slot_ptr"), helper_enter.get("lhs_slot_ptr")
            ),
            "helper_return_eax_matches_compare_lhs_ptr": _pointer_text_equal(
                helper_return.get("eax_ptr"), compare_lhs_ptr
            ),
            "helper_return_eax_preview_matches_compare_lhs": _preview_text_equal(
                helper_return.get("eax_preview_hex"), compare_lhs_preview
            ),
            "helper_return_slot_matches_compare_lhs_ptr": _pointer_text_equal(
                helper_return.get("lhs_slot_ptr"), compare_lhs_ptr
            ),
            "helper_return_slot_preview_matches_compare_lhs": _preview_text_equal(
                helper_return.get("lhs_slot_preview_hex"), compare_lhs_preview
            ),
            "pre_compare_esi_matches_compare_lhs_ptr": _pointer_text_equal(
                pre_compare.get("esi_ptr"), compare_lhs_ptr
            ),
        },
    }


def _normalize_slice_observation(item: dict[str, object], candidate_hex: str) -> dict[str, object]:
    normalized = _normalize_handoff_observation(item, candidate_hex)
    normalized.update(
        {
            "return_address": str(item.get("return_address", "")),
            "return_address_module_offset": str(item.get("return_address_module_offset", "")),
            "stack_words": list(item.get("stack_words", [])) if isinstance(item.get("stack_words"), list) else [],
            "argument_previews": dict(item.get("argument_previews", {}))
            if isinstance(item.get("argument_previews"), dict)
            else {},
        }
    )
    return normalized


def _aggregate_slice_hook_results(candidate_results: list[dict[str, object]]) -> dict[str, str]:
    base = _aggregate_handoff_hook_results(candidate_results)
    names: set[str] = set()
    for result in candidate_results:
        for item in result.get("hook_observations", []):
            if isinstance(item, dict):
                names.add(str(item.get("hook_name", "")))
    base.update(
        {
            "post_handoff_after_reload": "available" if "post_handoff_after_reload" in names else "unavailable",
            "pre_compare_push_esi": "available" if "pre_compare_push_esi" in names else "unavailable",
        }
    )
    return base


def _cross_candidate_slice_summary(candidate_results: list[dict[str, object]]) -> dict[str, object]:
    relation_counts: dict[str, int] = {}
    candidate_dependent_fields: dict[str, bool] = {}
    field_values: dict[str, set[str]] = {
        "helper_return.eax_preview_hex": set(),
        "helper_return.lhs_slot_preview_hex": set(),
        "compare_lhs.lhs_preview_hex": set(),
        "pre_call.esi_ptr": set(),
    }
    for result in candidate_results:
        arg_map = result.get("helper_argument_map", {})
        if not isinstance(arg_map, dict):
            continue
        relations = arg_map.get("relations", {})
        if isinstance(relations, dict):
            for key, value in relations.items():
                relation_counts[key] = relation_counts.get(key, 0) + (1 if bool(value) else 0)
        helper_return = arg_map.get("helper_return", {})
        compare_lhs = arg_map.get("compare_lhs", {})
        pre_call = arg_map.get("pre_call", {})
        if isinstance(helper_return, dict):
            field_values["helper_return.eax_preview_hex"].add(str(helper_return.get("eax_preview_hex", ""))[:48])
            field_values["helper_return.lhs_slot_preview_hex"].add(str(helper_return.get("lhs_slot_preview_hex", ""))[:48])
        if isinstance(compare_lhs, dict):
            field_values["compare_lhs.lhs_preview_hex"].add(str(compare_lhs.get("lhs_preview_hex", ""))[:48])
        if isinstance(pre_call, dict):
            field_values["pre_call.esi_ptr"].add(str(pre_call.get("esi_ptr", "")))
    for key, values in field_values.items():
        candidate_dependent_fields[key] = len({value for value in values if value}) > 1
    return {
        "candidate_count": len(candidate_results),
        "runtime_backed_count": sum(1 for item in candidate_results if bool(item.get("runtime_backed"))),
        "relation_counts": relation_counts,
        "candidate_dependent_fields": candidate_dependent_fields,
    }


def _classify_handoff_slice(
    *,
    runtime_backed_count: int,
    hook_results: dict[str, str],
    cross_summary: dict[str, object],
) -> str:
    if runtime_backed_count <= 0:
        return "needs_pre_rc4_base64_probe"
    relation_counts = cross_summary.get("relation_counts", {})
    relation_counts = relation_counts if isinstance(relation_counts, dict) else {}
    helper_available = (
        hook_results.get("handoff_helper_enter") == "available"
        and hook_results.get("handoff_helper_return") == "available"
    )
    compare_available = hook_results.get("compare_lhs_buffer") == "available"
    helper_to_compare = any(
        int(relation_counts.get(key, 0) or 0) > 0
        for key in (
            "helper_return_eax_matches_compare_lhs_ptr",
            "helper_return_eax_preview_matches_compare_lhs",
            "helper_return_slot_matches_compare_lhs_ptr",
            "helper_return_slot_preview_matches_compare_lhs",
            "pre_compare_esi_matches_compare_lhs_ptr",
        )
    )
    if (
        helper_available
        and compare_available
        and hook_results.get("post_handoff_lhs_reload") == "unavailable"
        and (
            hook_results.get("post_handoff_after_reload") == "available"
            or int(relation_counts.get("helper_return_eax_preview_matches_compare_lhs", 0) or 0) > 0
        )
    ):
        return "wrong_reload_anchor"
    if helper_available and compare_available and helper_to_compare:
        return "helper_arg_slice_confirmed"
    if helper_available or compare_available:
        return "helper_arg_slice_partial"
    return "wrong_helper_assumption"


def run_compare_handoff_slice_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log=None,
) -> dict[str, object]:
    _ = transform_model
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / COMPARE_HANDOFF_SLICE_PROBE_FILE_NAME
    script_path = _compare_handoff_slice_probe_script_path()
    static_audit = _compare_stack_static_audit(target)
    hook_points = _compare_handoff_slice_hook_points(static_audit)
    entries = list(COMPARE_HANDOFF_SLICE_PROBE_CANDIDATES)
    payload: dict[str, object] = {
        "artifact_kind": "compare_handoff_slice_probe",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(COMPARE_HANDOFF_SLICE_PROBE_CANDIDATES),
        "static_audit": {
            "classification": static_audit.get("classification"),
            "compare_site": static_audit.get("compare_site"),
            "backward_slice": static_audit.get("backward_slice", []),
            "prior_reload_anchor": "module+0x2559",
            "corrected_post_helper_probe": "helper onLeave plus module+0x255c fallback",
        },
        "hook_points": hook_points,
        "promotable_validations": [],
    }
    _write_json(result_path, payload)
    if not script_path.exists():
        raise RuntimeError(f"Compare handoff slice probe script missing: {script_path}")

    points_path = artifacts_dir / "hook_points.json"
    _write_json(points_path, {"hook_points": hook_points})
    candidate_results: list[dict[str, object]] = []
    for idx, candidate_hex in enumerate(entries, 1):
        candidate_dir = artifacts_dir / f"candidate_{idx}"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        compare_out = candidate_dir / "compare_handoff_slice_probe.json"
        compare_log = candidate_dir / "compare_handoff_slice_probe.log"
        command = [
            sys.executable,
            str(script_path),
            "--target",
            str(target),
            "--out",
            str(compare_out),
            "--points",
            str(points_path),
            "--probe-hex",
            candidate_hex,
            "--per-probe-timeout",
            str(per_probe_timeout),
        ]
        if log:
            log(f"CompareHandoffSliceProbe scripted hooks {idx}: {candidate_hex}")
        proc = subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        compare_log.write_text(
            f"[stdout]\n{proc.stdout or ''}\n\n[stderr]\n{proc.stderr or ''}",
            encoding="utf-8",
        )
        compare_payload = _read_json_object(compare_out) if compare_out.exists() else {}
        observations = [
            _normalize_slice_observation(dict(item), candidate_hex)
            for item in compare_payload.get("hook_observations", [])
            if isinstance(item, dict)
        ]
        arg_map = _helper_arg_map_from_observations(observations)
        candidate_results.append(
            {
                "label": f"compare_handoff_slice_probe_{idx}",
                "candidate_hex": candidate_hex,
                "candidate_prefix": candidate_hex[:16],
                "runtime_backed": bool(observations),
                "hook_results": dict(compare_payload.get("hook_results", {}))
                if isinstance(compare_payload.get("hook_results"), dict)
                else {},
                "helper_argument_map": arg_map,
                "hook_observations": observations[:40],
                "result_path": str(compare_out),
                "log_path": str(compare_log),
                "success": bool(compare_payload.get("success")),
                "error": str(compare_payload.get("error", "")),
            }
        )

    runtime_backed_count = sum(1 for item in candidate_results if bool(item.get("runtime_backed")))
    hook_results = _aggregate_slice_hook_results(candidate_results)
    cross_summary = _cross_candidate_slice_summary(candidate_results)
    classification = _classify_handoff_slice(
        runtime_backed_count=runtime_backed_count,
        hook_results=hook_results,
        cross_summary=cross_summary,
    )
    next_bounded_action = {
        "helper_arg_slice_confirmed": "derive byte-level constraints from the confirmed helper-to-compare lhs relation",
        "helper_arg_slice_partial": "tighten helper argument capture before candidate refinement",
        "wrong_reload_anchor": "replace module+0x2559 with an instruction-confirmed post-helper hook point",
        "wrong_helper_assumption": "move to the next bounded pre-compare transform handoff target",
        "needs_pre_rc4_base64_probe": "return to pre-RC4/Base64 dynamic material capture with new hookable offsets only",
    }.get(classification, "inspect helper argument slice artifact")
    payload.update(
        {
            "classification": classification,
            "runtime_backed_count": runtime_backed_count,
            "hook_results": hook_results,
            "candidate_results": candidate_results,
            "helper_argument_maps": [
                result.get("helper_argument_map", {}) for result in candidate_results
            ],
            "cross_candidate_summary": cross_summary,
            "findings": [
                "helper argument slice captured runtime observations"
                if runtime_backed_count
                else "helper argument slice did not capture runtime observations",
                "candidate generation, ranking, final selection, and search budget were unchanged",
            ],
            "next_bounded_action": next_bounded_action,
            "promotable_validations": [],
        }
    )
    _write_json(result_path, payload)
    if log:
        log(f"Compare handoff slice probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "validations": candidate_results,
        "promotable_validations": [],
    }


RETURN_SITE_EXPECTED_INSTRUCTIONS = (
    {
        "rva": 0x253A,
        "size": 6,
        "instruction": "mov dword ptr [ebp - 0x1170], eax",
        "operation": "store candidate output pointer into [ebp-0x1170]",
    },
    {
        "rva": 0x2554,
        "size": 5,
        "instruction": "call 0x401b50",
        "operation": "handoff/copy helper before compare buffer reload",
    },
    {
        "rva": 0x2559,
        "size": 6,
        "instruction": "mov esi, dword ptr [ebp - 0x1170]",
        "operation": "reload compare lhs pointer from [ebp-0x1170]",
    },
    {"rva": 0x2584, "size": 2, "instruction": "push 5", "operation": "set wide compare count"},
    {"rva": 0x2586, "size": 5, "instruction": "push 0x551c4c", "operation": "push wide flag target"},
    {"rva": 0x258B, "size": 1, "instruction": "push esi", "operation": "push compare lhs pointer"},
    {"rva": 0x258C, "size": 5, "instruction": "call 0x5028ac", "operation": "case-insensitive wide compare call"},
)


def _read_rva_bytes(data: bytes, sections: Sequence[dict[str, int]], rva: int, size: int) -> str:
    offset = _rva_to_file_offset(rva, sections)
    if offset is None or offset < 0 or offset >= len(data):
        return ""
    return data[offset:offset + max(0, size)].hex()


def _compare_handoff_return_site_static_audit(
    target: Path,
    hook_points: list[dict[str, object]],
) -> dict[str, object]:
    try:
        data = target.read_bytes()
    except Exception:
        data = b""
    sections = _pe_sections_for_rva_mapping(data)
    window_start = 0x253A
    window_end = 0x2591
    instructions: list[dict[str, object]] = []
    for item in RETURN_SITE_EXPECTED_INSTRUCTIONS:
        rva = int(item["rva"])
        size = int(item["size"])
        instructions.append(
            {
                **item,
                "rva": f"0x{rva:x}",
                "end_rva": f"0x{rva + size:x}",
                "bytes_hex": _read_rva_bytes(data, sections, rva, size),
            }
        )
    hook_audit: list[dict[str, object]] = []
    for point in hook_points:
        offset = _parse_int_hex(point.get("module_offset"))
        containing = None
        starts_instruction = None
        if offset is not None:
            for instruction in RETURN_SITE_EXPECTED_INSTRUCTIONS:
                start = int(instruction["rva"])
                end = start + int(instruction["size"])
                if offset == start:
                    starts_instruction = instruction
                    break
                if start < offset < end:
                    containing = instruction
                    break
        if starts_instruction is not None:
            status = "instruction_confirmed"
            reason = "hook point is at a known instruction boundary"
        elif containing is not None:
            status = "inside_instruction"
            reason = f"hook point falls inside instruction at 0x{int(containing['rva']):x}"
        else:
            status = "unknown_boundary"
            reason = "hook point is not in the bounded instruction map"
        hook_audit.append(
            {
                "name": point.get("name", ""),
                "module_offset": f"0x{offset:x}" if offset is not None else "",
                "address": point.get("address", ""),
                "boundary_status": status,
                "reason": reason,
            }
        )
    return {
        "classification": "static_return_site_audit_complete" if data and sections else "static_return_site_audit_partial",
        "byte_window": {
            "start_rva": f"0x{window_start:x}",
            "end_rva": f"0x{window_end:x}",
            "bytes_hex": _read_rva_bytes(data, sections, window_start, window_end - window_start),
        },
        "instruction_boundaries": instructions,
        "hook_point_audit": hook_audit,
    }


def _normalize_return_site_observation(item: dict[str, object], candidate_hex: str) -> dict[str, object]:
    normalized = _normalize_slice_observation(item, candidate_hex)
    normalized.update(
        {
            "helper_enter_return_address": str(item.get("helper_enter_return_address", "")),
            "helper_enter_return_address_module_offset": str(
                item.get("helper_enter_return_address_module_offset", "")
            ),
            "compare_args": dict(item.get("compare_args", {})) if isinstance(item.get("compare_args"), dict) else {},
        }
    )
    return normalized


def _compare_arg_list(compare_observation: dict[str, object]) -> list[dict[str, object]]:
    compare_args = compare_observation.get("compare_args", {})
    if isinstance(compare_args, dict) and isinstance(compare_args.get("args"), list):
        return [dict(item) for item in compare_args.get("args", []) if isinstance(item, dict)]
    args: list[dict[str, object]] = []
    lhs_ptr = str(compare_observation.get("lhs_ptr", ""))
    rhs_ptr = str(compare_observation.get("rhs_ptr", ""))
    if lhs_ptr:
        args.append(
            {
                "index": 0,
                "esp_relative": "+0x0",
                "value": lhs_ptr,
                "preview_hex": compare_observation.get("lhs_buffer_preview_hex", ""),
                "preview_utf16le": compare_observation.get("lhs_buffer_preview_utf16le", ""),
            }
        )
    if rhs_ptr:
        args.append({"index": 1, "esp_relative": "+0x4", "value": rhs_ptr, "preview_hex": ""})
    if compare_observation.get("compare_count") is not None:
        args.append({"index": 2, "esp_relative": "+0x8", "value_u32": compare_observation.get("compare_count")})
    return args


def _compare_arg_at(args: list[dict[str, object]], index: int) -> dict[str, object]:
    for item in args:
        try:
            item_index = int(item.get("index", -1))
        except (TypeError, ValueError):
            item_index = -1
        if item_index == index:
            return item
    return {}


def _preview_has_flag_prefix(item: dict[str, object]) -> bool:
    preview_hex = str(item.get("preview_hex", "")).lower()
    preview_text = str(item.get("preview_utf16le", "")).lower()
    return preview_hex.startswith("66006c00610067007b00") or preview_text.startswith("flag{")


def _return_site_map_from_observations(observations: list[dict[str, object]]) -> dict[str, object]:
    helper_enter = _first_observation(observations, "handoff_helper_enter")
    helper_return = _first_observation(observations, "handoff_helper_return")
    return_site = next(
        (item for item in observations if str(item.get("hook_name", "")).startswith("helper_return_site_")),
        {},
    )
    compare = _first_observation(observations, "wide_flag_prefix_compare")
    pre_compare = _first_observation(observations, "pre_compare_push_esi")
    args = _compare_arg_list(compare)
    arg0 = _compare_arg_at(args, 0)
    arg1 = _compare_arg_at(args, 1)
    helper_enter_return_offset = str(
        helper_return.get("helper_enter_return_address_module_offset")
        or helper_enter.get("return_address_module_offset")
        or ""
    )
    helper_return_eax_preview = str(helper_return.get("eax_preview_hex", ""))
    helper_return_esi_preview = str(helper_return.get("esi_preview_hex", ""))
    helper_return_slot_preview = str(helper_return.get("lhs_slot_preview_hex", ""))
    return {
        "helper_enter": {
            "return_address": helper_enter.get("return_address", ""),
            "return_address_module_offset": helper_enter.get("return_address_module_offset", ""),
            "matches_expected_post_helper": helper_enter_return_offset.lower() == "0x2559",
        },
        "helper_return": {
            "helper_enter_return_address": helper_return.get("helper_enter_return_address", ""),
            "helper_enter_return_address_module_offset": helper_enter_return_offset,
            "eax_ptr": helper_return.get("eax_ptr", ""),
            "eax_preview_hex": helper_return_eax_preview,
            "esi_ptr": helper_return.get("esi_ptr", ""),
            "esi_preview_hex": helper_return_esi_preview,
            "lhs_slot_ptr": helper_return.get("lhs_slot_ptr", ""),
            "lhs_slot_preview_hex": helper_return_slot_preview,
        },
        "return_site": {
            "observed": bool(return_site),
            "hook_name": return_site.get("hook_name", ""),
            "module_offset": return_site.get("module_offset", ""),
            "eax_ptr": return_site.get("eax_ptr", ""),
            "esi_ptr": return_site.get("esi_ptr", ""),
            "lhs_slot_ptr": return_site.get("lhs_slot_ptr", ""),
        },
        "compare_call": {
            "observed": bool(compare),
            "esp": dict(compare.get("registers", {})).get("esp", "") if isinstance(compare.get("registers"), dict) else "",
            "args": args,
            "arg0_preview_has_flag_prefix": _preview_has_flag_prefix(arg0),
            "arg1_preview_has_flag_prefix": _preview_has_flag_prefix(arg1),
        },
        "relations": {
            "helper_enter_return_matches_0x2559": helper_enter_return_offset.lower() == "0x2559",
            "helper_enter_return_is_0x233d": helper_enter_return_offset.lower() == "0x233d",
            "return_site_hook_observed": bool(return_site),
            "helper_return_eax_matches_compare_arg0_ptr": _pointer_text_equal(helper_return.get("eax_ptr"), arg0.get("value")),
            "helper_return_eax_matches_compare_arg1_ptr": _pointer_text_equal(helper_return.get("eax_ptr"), arg1.get("value")),
            "helper_return_esi_matches_compare_arg0_ptr": _pointer_text_equal(helper_return.get("esi_ptr"), arg0.get("value")),
            "helper_return_slot_matches_compare_arg0_ptr": _pointer_text_equal(
                helper_return.get("lhs_slot_ptr"), arg0.get("value")
            ),
            "helper_return_eax_preview_matches_compare_arg0": _preview_text_equal(
                helper_return_eax_preview, arg0.get("preview_hex")
            ),
            "helper_return_eax_preview_matches_compare_arg1": _preview_text_equal(
                helper_return_eax_preview, arg1.get("preview_hex")
            ),
            "pre_compare_esi_matches_compare_arg0_ptr": _pointer_text_equal(pre_compare.get("esi_ptr"), arg0.get("value")),
        },
    }


def _aggregate_return_site_hook_results(candidate_results: list[dict[str, object]]) -> dict[str, str]:
    names: set[str] = set()
    helper_return_site_available = False
    compare_args_available = False
    lhs_slot_available = False
    for result in candidate_results:
        for item in result.get("hook_observations", []):
            if not isinstance(item, dict):
                continue
            name = str(item.get("hook_name", ""))
            names.add(name)
            helper_return_site_available = helper_return_site_available or name.startswith("helper_return_site_")
            compare_args_available = compare_args_available or bool(item.get("compare_args"))
            lhs_slot_available = lhs_slot_available or bool(str(item.get("lhs_slot_ptr", "")))
    return {
        "handoff_helper_enter": "available" if "handoff_helper_enter" in names else "unavailable",
        "handoff_helper_return": "available" if "handoff_helper_return" in names else "unavailable",
        "helper_return_site": "available" if helper_return_site_available else "unavailable",
        "post_handoff_lhs_reload": "available" if "post_handoff_lhs_reload" in names else "unavailable",
        "post_handoff_after_reload": "available" if "post_handoff_after_reload" in names else "unavailable",
        "pre_compare_push_esi": "available" if "pre_compare_push_esi" in names else "unavailable",
        "wide_flag_prefix_compare": "available" if "wide_flag_prefix_compare" in names else "unavailable",
        "compare_call_args": "available" if compare_args_available else "unavailable",
        "lhs_slot": "available" if lhs_slot_available else "unavailable",
    }


def _cross_candidate_return_site_summary(candidate_results: list[dict[str, object]]) -> dict[str, object]:
    relation_counts: dict[str, int] = {}
    field_values: dict[str, set[str]] = {
        "helper_return.eax_preview_hex": set(),
        "helper_return.esi_preview_hex": set(),
        "helper_return.lhs_slot_preview_hex": set(),
        "compare_call.arg0.preview_hex": set(),
        "compare_call.arg1.preview_hex": set(),
        "compare_call.arg0.value": set(),
        "compare_call.arg1.value": set(),
        "helper_enter.return_address_module_offset": set(),
    }
    target_flag_side_counts = {"arg0": 0, "arg1": 0}
    for result in candidate_results:
        return_site_map = result.get("return_site_map", {})
        if not isinstance(return_site_map, dict):
            continue
        relations = return_site_map.get("relations", {})
        if isinstance(relations, dict):
            for key, value in relations.items():
                relation_counts[key] = relation_counts.get(key, 0) + (1 if bool(value) else 0)
        helper_return = return_site_map.get("helper_return", {})
        helper_enter = return_site_map.get("helper_enter", {})
        compare_call = return_site_map.get("compare_call", {})
        if isinstance(helper_return, dict):
            field_values["helper_return.eax_preview_hex"].add(str(helper_return.get("eax_preview_hex", ""))[:48])
            field_values["helper_return.esi_preview_hex"].add(str(helper_return.get("esi_preview_hex", ""))[:48])
            field_values["helper_return.lhs_slot_preview_hex"].add(str(helper_return.get("lhs_slot_preview_hex", ""))[:48])
        if isinstance(helper_enter, dict):
            field_values["helper_enter.return_address_module_offset"].add(
                str(helper_enter.get("return_address_module_offset", ""))
            )
        if isinstance(compare_call, dict):
            args = compare_call.get("args", [])
            args = args if isinstance(args, list) else []
            arg0 = _compare_arg_at([dict(item) for item in args if isinstance(item, dict)], 0)
            arg1 = _compare_arg_at([dict(item) for item in args if isinstance(item, dict)], 1)
            field_values["compare_call.arg0.preview_hex"].add(str(arg0.get("preview_hex", ""))[:48])
            field_values["compare_call.arg1.preview_hex"].add(str(arg1.get("preview_hex", ""))[:48])
            field_values["compare_call.arg0.value"].add(str(arg0.get("value", "")))
            field_values["compare_call.arg1.value"].add(str(arg1.get("value", "")))
            target_flag_side_counts["arg0"] += 1 if _preview_has_flag_prefix(arg0) else 0
            target_flag_side_counts["arg1"] += 1 if _preview_has_flag_prefix(arg1) else 0
    return {
        "candidate_count": len(candidate_results),
        "runtime_backed_count": sum(1 for item in candidate_results if bool(item.get("runtime_backed"))),
        "relation_counts": relation_counts,
        "candidate_dependent_fields": {
            key: len({value for value in values if value}) > 1 for key, values in field_values.items()
        },
        "target_flag_side_counts": target_flag_side_counts,
    }


def _classify_handoff_return_site(
    *,
    runtime_backed_count: int,
    hook_results: dict[str, str],
    cross_summary: dict[str, object],
    static_audit: dict[str, object],
) -> str:
    if runtime_backed_count <= 0:
        return "needs_pre_rc4_base64_probe"
    relation_counts = cross_summary.get("relation_counts", {})
    relation_counts = relation_counts if isinstance(relation_counts, dict) else {}
    target_counts = cross_summary.get("target_flag_side_counts", {})
    target_counts = target_counts if isinstance(target_counts, dict) else {}
    candidate_dependent = cross_summary.get("candidate_dependent_fields", {})
    candidate_dependent = candidate_dependent if isinstance(candidate_dependent, dict) else {}
    hook_audit = static_audit.get("hook_point_audit", [])
    hook_audit = hook_audit if isinstance(hook_audit, list) else []
    inside_reload_fallback = any(
        isinstance(item, dict)
        and item.get("name") == "post_handoff_after_reload"
        and item.get("boundary_status") == "inside_instruction"
        for item in hook_audit
    )
    candidate_count = int(cross_summary.get("candidate_count", 0) or 0)
    if int(relation_counts.get("helper_enter_return_is_0x233d", 0) or 0) > 0:
        return "wrong_helper_assumption"
    if hook_results.get("wide_flag_prefix_compare") != "available" or hook_results.get("compare_call_args") != "available":
        return "wrong_compare_arg_capture"
    if (
        candidate_count
        and int(target_counts.get("arg0", 0) or 0) == candidate_count
        and bool(candidate_dependent.get("compare_call.arg1.preview_hex"))
    ):
        return "compare_args_swapped"
    if (
        candidate_count
        and int(target_counts.get("arg1", 0) or 0) == candidate_count
        and bool(candidate_dependent.get("compare_call.arg0.preview_hex"))
        and (
            int(relation_counts.get("helper_return_eax_matches_compare_arg0_ptr", 0) or 0) > 0
            or int(relation_counts.get("helper_return_eax_preview_matches_compare_arg0", 0) or 0) > 0
            or int(relation_counts.get("pre_compare_esi_matches_compare_arg0_ptr", 0) or 0) > 0
        )
    ):
        return "return_site_confirmed"
    if (
        inside_reload_fallback
        and hook_results.get("post_handoff_lhs_reload") == "unavailable"
        and int(relation_counts.get("helper_enter_return_matches_0x2559", 0) or 0) > 0
    ):
        return "wrong_reload_anchor"
    return "helper_arg_slice_still_partial"


def _return_site_hit_summary(candidate_results: list[dict[str, object]]) -> dict[str, int]:
    hit_0x2338 = 0
    hit_0x233d = 0
    hit_0x234e = 0
    hit_0x2355 = 0
    call_entered = 0
    call_returned = 0
    for result in candidate_results:
        observations = result.get("hook_observations", [])
        observations = observations if isinstance(observations, list) else []
        names = {
            str(item.get("hook_name", ""))
            for item in observations
            if isinstance(item, dict)
        }
        if "handoff_helper_enter" in names:
            hit_0x2338 += 1
            call_entered += 1
        if any(name.startswith("helper_return_site_0x233d") for name in names):
            hit_0x233d += 1
        if "handoff_helper_return" in names:
            call_returned += 1
        if any(name.startswith("producer_pre_output_call") for name in names):
            hit_0x234e += 1
        if any(name.startswith("producer_pre_second_call") for name in names):
            hit_0x2355 += 1
    return {
        "hit_0x2338_count": hit_0x2338,
        "hit_0x233d_count": hit_0x233d,
        "hit_0x234e_count": hit_0x234e,
        "hit_0x2355_count": hit_0x2355,
        "call_0x401b50_entered_count": call_entered,
        "call_0x401b50_returned_count": call_returned,
    }


def run_compare_handoff_return_site_probe(
    *,
    target: Path,
    artifacts_dir: Path,
    transform_model: SamplereverseTransformModel,
    per_probe_timeout: float,
    log=None,
) -> dict[str, object]:
    _ = transform_model
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    result_path = artifacts_dir / COMPARE_HANDOFF_RETURN_SITE_PROBE_FILE_NAME
    script_path = _compare_handoff_return_site_probe_script_path()
    hook_points = _compare_handoff_slice_hook_points(_compare_stack_static_audit(target))
    static_audit = _compare_handoff_return_site_static_audit(target, hook_points)
    entries = list(COMPARE_HANDOFF_RETURN_SITE_PROBE_CANDIDATES)
    payload: dict[str, object] = {
        "artifact_kind": "compare_handoff_return_site_probe",
        "profile": "samplereverse",
        "attempted": True,
        "candidate_generation_changed": False,
        "ranking_changed": False,
        "final_selection_changed": False,
        "search_budget_changed": False,
        "beam_budget_topn_timeout_frontier_limit_expanded": False,
        "candidate_count": len(entries),
        "candidate_limit": len(COMPARE_HANDOFF_RETURN_SITE_PROBE_CANDIDATES),
        "static_audit": static_audit,
        "hook_points": hook_points,
        "promotable_validations": [],
    }
    _write_json(result_path, payload)
    if not script_path.exists():
        raise RuntimeError(f"Compare handoff return-site probe script missing: {script_path}")

    points_path = artifacts_dir / "hook_points.json"
    _write_json(points_path, {"hook_points": hook_points})
    candidate_results: list[dict[str, object]] = []
    for idx, candidate_hex in enumerate(entries, 1):
        candidate_dir = artifacts_dir / f"candidate_{idx}"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        compare_out = candidate_dir / "compare_handoff_return_site_probe.json"
        compare_log = candidate_dir / "compare_handoff_return_site_probe.log"
        command = [
            sys.executable,
            str(script_path),
            "--target",
            str(target),
            "--out",
            str(compare_out),
            "--points",
            str(points_path),
            "--probe-hex",
            candidate_hex,
            "--per-probe-timeout",
            str(per_probe_timeout),
        ]
        if log:
            log(f"CompareHandoffReturnSiteProbe scripted hooks {idx}: {candidate_hex}")
        proc = subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        compare_log.write_text(
            f"[stdout]\n{proc.stdout or ''}\n\n[stderr]\n{proc.stderr or ''}",
            encoding="utf-8",
        )
        compare_payload = _read_json_object(compare_out) if compare_out.exists() else {}
        observations = [
            _normalize_return_site_observation(dict(item), candidate_hex)
            for item in compare_payload.get("hook_observations", [])
            if isinstance(item, dict)
        ]
        candidate_results.append(
            {
                "label": f"compare_handoff_return_site_probe_{idx}",
                "candidate_hex": candidate_hex,
                "candidate_prefix": candidate_hex[:16],
                "runtime_backed": bool(observations),
                "hook_results": dict(compare_payload.get("hook_results", {}))
                if isinstance(compare_payload.get("hook_results"), dict)
                else {},
                "return_site_map": _return_site_map_from_observations(observations),
                "hook_observations": observations[:48],
                "result_path": str(compare_out),
                "log_path": str(compare_log),
                "success": bool(compare_payload.get("success")),
                "error": str(compare_payload.get("error", "")),
            }
        )

    runtime_backed_count = sum(1 for item in candidate_results if bool(item.get("runtime_backed")))
    hook_results = _aggregate_return_site_hook_results(candidate_results)
    cross_summary = _cross_candidate_return_site_summary(candidate_results)
    hit_summary = _return_site_hit_summary(candidate_results)
    classification = _classify_handoff_return_site(
        runtime_backed_count=runtime_backed_count,
        hook_results=hook_results,
        cross_summary=cross_summary,
        static_audit=static_audit,
    )
    next_bounded_action = {
        "return_site_confirmed": "derive byte-level constraints from the confirmed post-helper compare lhs relation",
        "wrong_reload_anchor": "replace invalid post-helper hook offsets with instruction-boundary hooks from the return-site audit",
        "compare_args_swapped": "correct compare-call argument interpretation before deriving constraints",
        "wrong_compare_arg_capture": "repair compare-call stack capture before any candidate refinement",
        "wrong_helper_assumption": "move to the next bounded pre-compare handoff target; 0x401b50 did not return to module+0x2559",
        "helper_arg_slice_still_partial": "use the return-site artifact to select a narrower hook anchor before searching",
        "needs_pre_rc4_base64_probe": "return to pre-RC4/Base64 dynamic material capture with new hookable offsets only",
    }.get(classification, "inspect compare handoff return-site artifact")
    payload.update(
        {
            "classification": classification,
            "runtime_backed_count": runtime_backed_count,
            "hook_results": hook_results,
            "candidate_results": candidate_results,
            "return_site_maps": [result.get("return_site_map", {}) for result in candidate_results],
            "cross_candidate_summary": cross_summary,
            **hit_summary,
            "findings": [
                "return-site audit captured runtime observations"
                if runtime_backed_count
                else "return-site audit did not capture runtime observations",
                "candidate generation, ranking, final selection, and search budget were unchanged",
            ],
            "next_bounded_action": next_bounded_action,
            "promotable_validations": [],
        }
    )
    _write_json(result_path, payload)
    if log:
        log(f"Compare handoff return-site probe wrote {result_path}")
    return {
        "result_path": str(result_path),
        "payload": payload,
        "validations": candidate_results,
        "promotable_validations": [],
    }


